t.script:
function toggleOdooPwd(inputId, btn) {
    var inp = document.getElementById(inputId);
    if (!inp) return;
    var isPwd = inp.type === 'password';
    inp.type = isPwd ? 'text' : 'password';
    var openEye = btn.querySelector('.icon-eye-open');
    var closedEye = btn.querySelector('.icon-eye-closed');
    if (openEye && closedEye) {
        openEye.style.display = isPwd ? 'none' : 'block';
        closedEye.style.display = isPwd ? 'block' : 'none';
    }
}

function togglePortalTypeMenu(e) {
    if (e) e.stopPropagation();
    var menu = document.getElementById('portalTypeMenu');
    var btn = document.getElementById('portalTypeBtn');
    if (menu) {
        menu.classList.toggle('d-none');
        if (btn) btn.classList.toggle('active', !menu.classList.contains('d-none'));
    }
}

function selectPortalType(val, text, e) {
    if (e) e.stopPropagation();
    var sel = document.getElementById('odooPortalType');
    var disp = document.getElementById('portalTypeDisplay');
    var btn = document.getElementById('portalTypeBtn');
    if (sel) {
        sel.value = val;
        handlePortalTypeChange(val);
    }
    if (disp) disp.innerText = text;
    var menu = document.getElementById('portalTypeMenu');
    if (menu) {
        menu.classList.add('d-none');
        if (btn) btn.classList.remove('active');
        var items = menu.querySelectorAll('.hdesk-dropdown-menu-item');
        items.forEach(function(item) {
            item.classList.toggle('active', item.getAttribute('data-value') === val);
        });
    }
}

document.addEventListener('click', function(e) {
    var menu = document.getElementById('portalTypeMenu');
    var btn = document.getElementById('portalTypeBtn');
    if (menu && !menu.classList.contains('d-none') && btn && !btn.contains(e.target) && !menu.contains(e.target)) {
        menu.classList.add('d-none');
        btn.classList.remove('active');
    }
    var wMenu = document.getElementById('wizardUserTypeMenu');
    var wBtn = document.getElementById('wizardUserTypeBtn');
    if (wMenu && !wMenu.classList.contains('d-none') && wBtn && !wBtn.contains(e.target) && !wMenu.contains(e.target)) {
        wMenu.classList.add('d-none');
        wBtn.classList.remove('active');
    }
});

function handlePortalTypeChange(val) {
    var emailInp = document.getElementById('odooInpEmail');
    var pwdInp = document.getElementById('odooInpPassword');
    var lblEmail = document.getElementById('lblInpEmail');
    var subtitle = document.getElementById('lblLoginSubtitle');
    emailInp.value = '';
    pwdInp.value = '';
    if (val === 'customer') {
        if (lblEmail) lblEmail.innerText = 'Username or Email';
        emailInp.placeholder = 'you@company.com or username';
        if (subtitle) subtitle.innerText = 'Enter your details to access your support dashboard';
    } else {
        if (lblEmail) lblEmail.innerText = 'Username or Email';
        emailInp.placeholder = 'employee@company.com or username';
        if (subtitle) subtitle.innerText = 'Enter your details to access your support dashboard';
    }
}

function showOdooBanner(type, msg, showSpinner) {
    var banner = document.getElementById('odooVerifyBanner');
    banner.className = 'alert alert-' + type + ' d-flex align-items-center gap-2 py-1 px-3 mb-2 small';
    document.getElementById('odooVerifySpinner').classList.toggle('d-none', !showSpinner);
    document.getElementById('odooVerifyMsg').innerHTML = msg;
}

function handleOdooSignIn(e) {
    e.preventDefault();
    var portalType = document.getElementById('odooPortalType').value;
    var email = document.getElementById('odooInpEmail').value.trim();
    var pwd = document.getElementById('odooInpPassword').value;
    var btn = document.getElementById('btnOdooSignInSubmit');

    btn.disabled = true;
    showOdooBanner('info', 'Verifying credentials...', true);

    fetch('/helpdesk/auth/verify', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
            jsonrpc: '2.0',
            params: { email: email, password: pwd, portal_type: portalType, action: 'signin' }
        })
    }).then(function(r) { return r.json(); }).then(function(resp) {
        var res = resp.result || {};
        if (res.success) {
            var pType = res.portal_type || portalType;
            if (pType === 'employee') {
                var eId = res.emp_id || '';
                var eEmail = res.emp_email || email;
                if (eId) {
                    document.cookie = "helpdesk_employee_id=" + eId + "; path=/; max-age=2592000; SameSite=Lax";
                    try { localStorage.setItem('helpdesk_employee_id', eId); } catch(e) {}
                }
                if (eEmail) {
                    document.cookie = "helpdesk_employee_email=" + encodeURIComponent(eEmail) + "; path=/; max-age=2592000; SameSite=Lax";
                    try { localStorage.setItem('helpdesk_employee_email', eEmail); } catch(e) {}
                }
                document.cookie = "helpdesk_portal_type=employee; path=/; max-age=2592000; SameSite=Lax";
                try { localStorage.setItem('helpdesk_portal_type', 'employee'); } catch(e) {}
            } else {
                var pId = res.partner_id || '';
                var pEmail = res.customer_email || email;
                if (pId) {
                    document.cookie = "helpdesk_customer_partner_id=" + pId + "; path=/; max-age=2592000; SameSite=Lax";
                    try { localStorage.setItem('helpdesk_customer_partner_id', pId); } catch(e) {}
                }
                if (pEmail) {
                    document.cookie = "helpdesk_customer_email=" + encodeURIComponent(pEmail) + "; path=/; max-age=2592000; SameSite=Lax";
                    try { localStorage.setItem('helpdesk_customer_email', pEmail); } catch(e) {}
                }
                document.cookie = "helpdesk_portal_type=customer; path=/; max-age=2592000; SameSite=Lax";
                try { localStorage.setItem('helpdesk_portal_type', 'customer'); } catch(e) {}
            }
            showOdooBanner('success', ' ' + res.message, false);
            setTimeout(function() {
                window.location.href = res.redirect || (portalType === 'employee' ? '/helpdesk/employee' : '/helpdesk/portal?guest=1');
            }, 500);
        } else {
            btn.disabled = false;
            showOdooBanner('danger', ' ' + (res.message || 'Verification failed.'), false);
        }
    }).catch(function() {
        btn.disabled = false;
        showOdooBanner('danger', 'Server verification error.', false);
    });
}

document.addEventListener('DOMContentLoaded', function() {
    var sel = document.getElementById('odooPortalType');
    if (sel) {
        var val = sel.value;
        var lblEmail = document.getElementById('lblInpEmail');
        var emailInp = document.getElementById('odooInpEmail');
        var subtitle = document.getElementById('lblLoginSubtitle');
        var disp = document.getElementById('portalTypeDisplay');
        if (disp) disp.innerText = (val === 'employee' ? 'Employee' : 'Customer');
        if (lblEmail) lblEmail.innerText = 'Username or Email';
        if (emailInp) emailInp.placeholder = 'you@company.com or username';
        if (subtitle) subtitle.innerText = 'Enter your details to access your support dashboard';
    }

    // Suppress browser autofill suggestions on login fields
    var emailField = document.getElementById('odooInpEmail');
    var pwdField = document.getElementById('odooInpPassword');
    [emailField, pwdField].forEach(function(inp) {
        if (inp) {
            inp.setAttribute('readonly', 'readonly');
            inp.addEventListener('focus', function() {
                var self = this;
                setTimeout(function() {
                    self.removeAttribute('readonly');
                }, 50);
            });
        }
    });
});

// Modal Controllers
