        iconSvg: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#0878F9" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>',
        bodyHtml: '<div style="display:flex; flex-direction:column; gap:14px;">' +
            '<div><strong style="color:#101B35; font-size:14px; display:block; margin-bottom:4px;">1. Switching Portal Types</strong>' +
            '<p style="margin:0; color:#475569;">Select <strong>Customer</strong> if you are submitting or tracking your support tickets. Select <strong>Employee</strong> if you are an internal support agent or manager.</p></div>' +
            '<div><strong style="color:#101B35; font-size:14px; display:block; margin-bottom:4px;">2. Ticket Management</strong>' +
            '<p style="margin:0; color:#475569;">Create tickets with attachments, track real-time resolution stages, and converse with agents directly through the live chatter.</p></div>' +
            '<div><strong style="color:#101B35; font-size:14px; display:block; margin-bottom:4px;">3. Smart Knowledge Base</strong>' +
            '<p style="margin:0; color:#475569;">Search frequently asked questions and guides to find instantaneous resolutions without waiting.</p></div>' +
            '</div>'
    },
    privacy: {
        title: "Privacy Policy",
        subtitle: "Your data security and protection",
        iconBg: "#DCFCE7",
        iconSvg: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#10B981" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>',
        bodyHtml: '<div style="display:flex; flex-direction:column; gap:14px;">' +
            '<div><strong style="color:#101B35; font-size:14px; display:block; margin-bottom:4px;">Data Encryption</strong>' +
            '<p style="margin:0; color:#475569;">All communications and ticket payloads are protected with TLS 1.3 encryption and secure session tokens.</p></div>' +
            '<div><strong style="color:#101B35; font-size:14px; display:block; margin-bottom:4px;">Access Control</strong>' +
            '<p style="margin:0; color:#475569;">Strict role-based isolation guarantees that your private correspondence and business data remain accessible only to authorized agents.</p></div>' +
            '<div><strong style="color:#101B35; font-size:14px; display:block; margin-bottom:4px;">Compliance</strong>' +
            '<p style="margin:0; color:#475569;">We strictly comply with enterprise GDPR and SOC2 data privacy regulations.</p></div>' +
            '</div>'
    },
    terms: {
        title: "Terms of Service",
        subtitle: "Acceptable use and SLA policies",
        iconBg: "#FEF3C7",
        iconSvg: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#F5A000" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>',
        bodyHtml: '<div style="display:flex; flex-direction:column; gap:14px;">' +
            '<div><strong style="color:#101B35; font-size:14px; display:block; margin-bottom:4px;">Service Availability</strong>' +
            '<p style="margin:0; color:#475569;">We maintain 99.9% portal uptime with automated load balancing and continuous backup mirroring.</p></div>' +
            '<div><strong style="color:#101B35; font-size:14px; display:block; margin-bottom:4px;">Support SLAs</strong>' +
            '<p style="margin:0; color:#475569;">Urgent production tickets are responded to within 30 minutes; standard tickets are handled during standard support windows.</p></div>' +
            '<div><strong style="color:#101B35; font-size:14px; display:block; margin-bottom:4px;">User Responsibility</strong>' +
            '<p style="margin:0; color:#475569;">Keep user credentials confidential. Unauthorized access attempts are monitored and recorded.</p></div>' +
            '</div>'
    },
    support: {
        title: "Support Directory",
        subtitle: "Reach our dedicated support team",
        iconBg: "#F3E8FF",
        iconSvg: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#8B5CF6" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg>',
        bodyHtml: '<div style="display:flex; flex-direction:column; gap:12px;">' +
            '<div style="background:#F8FAFC; border:1px solid #E2E8F0; border-radius:12px; padding:12px 16px;">' +
            '<strong style="color:#101B35; font-size:12px; text-transform:uppercase; letter-spacing:0.5px; display:block; margin-bottom:3px;">24/7 Priority Emergency Line</strong>' +
            '<span style="color:#0878F9; font-weight:800; font-size:16px;">+1 (800) 555-0199</span>' +
            '</div>' +
            '<div style="background:#F8FAFC; border:1px solid #E2E8F0; border-radius:12px; padding:12px 16px;">' +
            '<strong style="color:#101B35; font-size:12px; text-transform:uppercase; letter-spacing:0.5px; display:block; margin-bottom:3px;">Direct Support Email</strong>' +
            '<span style="color:#101B35; font-weight:600; font-size:14px;">support@helpdesk.local</span>' +
            '</div>' +
            '<p style="margin:0; color:#64748B; font-size:12px; line-height:1.4;">Our support specialists and duty managers are on standby to resolve any critical ticket requests.</p>' +
            '</div>'
    }
};

function openInfoModal(type) {
    var data = hdeskModalData[type];
    if (!data) return;
    var modal = document.getElementById('hdeskInfoModal');
    var icon = document.getElementById('hdeskModalIcon');
    var title = document.getElementById('hdeskModalTitle');
    var sub = document.getElementById('hdeskModalSubtitle');
    var body = document.getElementById('hdeskModalBody');
    if (icon) {
        icon.style.background = data.iconBg;
        icon.innerHTML = data.iconSvg;
    }
    if (title) title.innerText = data.title;
    if (sub) sub.innerText = data.subtitle;
    if (body) body.innerHTML = data.bodyHtml;
    if (modal) modal.classList.remove('d-none');
}

function closeInfoModal() {
    var modal = document.getElementById('hdeskInfoModal');
    if (modal) modal.classList.add('d-none');
}

// =========================================================
// 3-Step Forgot Password & OTP Wizard Controller
// =========================================================
var hdeskWizardState = {
    currentStep: 1,
    userType: 'customer',
    email: '',
    resetToken: '',
    cooldownInterval: null,
    cooldownSeconds: 0
};

function wizardShowAlert(msg, isError) {
    var box = document.getElementById('hdeskWizardAlert');
    if (!box) return;
    box.className = 'hdesk-wizard-alert ' + (isError ? 'hdesk-wizard-alert-error' : 'hdesk-wizard-alert-success');
    box.innerHTML = (isError ? '✕ ' : '✓ ') + msg;
    box.classList.remove('d-none');
}

function wizardClearAlert() {
    var box = document.getElementById('hdeskWizardAlert');
    if (box) {
        box.classList.add('d-none');
        box.innerHTML = '';
    }
}

function wizardSetStep(step) {
    hdeskWizardState.currentStep = step;
    wizardClearAlert();

    // Update Stepper Header
    [1, 2, 3].forEach(function(i) {
        var node = document.getElementById('hdeskWizardIndicator' + i);
        if (node) {
            if (i === step) node.classList.add('active');
            else node.classList.remove('active');
        }
        var content = document.getElementById('hdeskWizardStep' + i);
        if (content) {
            if (i === step) content.classList.remove('d-none');
            else content.classList.add('d-none');
        }
    });

    if (step === 1) {
        var emailInp = document.getElementById('hdeskWizardEmail');
        if (emailInp) setTimeout(function() { emailInp.focus(); }, 120);
    } else if (step === 2) {
        var dispEmail = document.getElementById('hdeskWizardDispEmail');
        if (dispEmail) dispEmail.textContent = hdeskWizardState.email;
        var digits = document.querySelectorAll('.hdesk-otp-digit');
        digits.forEach(function(d) {
            d.value = '';
            d.classList.remove('has-val');
        });
        if (digits[0]) setTimeout(function() { digits[0].focus(); }, 120);
    } else if (step === 3) {
        var userTypeField = document.getElementById('hdeskWizardStep3UserType');
        var emailField = document.getElementById('hdeskWizardStep3Email');
        if (userTypeField) userTypeField.value = (hdeskWizardState.userType === 'employee' ? 'Employee' : 'Customer');
        if (emailField) emailField.value = hdeskWizardState.email;
        var newPwd = document.getElementById('hdeskWizardNewPwd');
        var confPwd = document.getElementById('hdeskWizardConfirmPwd');
        if (newPwd) newPwd.value = '';
        if (confPwd) confPwd.value = '';
        if (newPwd) setTimeout(function() { newPwd.focus(); }, 120);
    }
}

function openForgotModal() {
    var modal = document.getElementById('hdeskForgotModal');
    var emailInp = document.getElementById('hdeskWizardEmail');
    var mainEmail = document.getElementById('odooInpEmail');
    var mainUserType = document.getElementById('odooPortalType');

    var initialType = 'customer';
    var initialText = 'Customer';
    if (mainUserType && mainUserType.value) {
        var curType = (mainUserType.value || '').toLowerCase();
        if (curType === 'employee') {
            initialType = 'employee';
            initialText = 'Employee';
        }
    }
    selectWizardUserType(initialType, initialText);

    if (emailInp) {
        if (mainEmail && mainEmail.value) {
            emailInp.value = mainEmail.value.trim();
        }
        handleWizardEmailInput();
    }

    var mainPwd = document.getElementById('odooInpPassword');
    if (mainPwd) {
        mainPwd.value = '';
    }
    try { sessionStorage.removeItem('hdesk_reset_token'); } catch(e){}
    var hiddenToken = document.getElementById('hdeskWizardResetToken');
    if (hiddenToken) hiddenToken.value = '';

    hdeskWizardState.userType = initialType;
    hdeskWizardState.email = (emailInp ? emailInp.value.trim() : '');
    hdeskWizardState.resetToken = '';

    wizardSetStep(1);
    if (modal) modal.classList.remove('d-none');
}

function toggleWizardUserTypeMenu(e) {
    if (e) e.stopPropagation();
    var menu = document.getElementById('wizardUserTypeMenu');
    var btn = document.getElementById('wizardUserTypeBtn');
    if (menu) {
        menu.classList.toggle('d-none');
        if (btn) btn.classList.toggle('active', !menu.classList.contains('d-none'));
    }
}

function selectWizardUserType(val, text, e) {
    if (e) e.stopPropagation();
    var sel = document.getElementById('hdeskWizardUserType');
    var disp = document.getElementById('wizardUserTypeDisplay');
    var btn = document.getElementById('wizardUserTypeBtn');
    if (sel) {
        sel.value = val;
        handleWizardUserTypeChange();
    }
    if (disp) disp.innerText = text;
    var menu = document.getElementById('wizardUserTypeMenu');
    if (menu) {
        menu.classList.add('d-none');
        if (btn) btn.classList.remove('active');
        var items = menu.querySelectorAll('.hdesk-dropdown-menu-item');
        items.forEach(function(item) {
            item.classList.toggle('active', item.getAttribute('data-value') === val);
        });
    }
}

function closeForgotModal() {
    var modal = document.getElementById('hdeskForgotModal');
    if (modal) modal.classList.add('d-none');
    if (hdeskWizardState.cooldownInterval) {
        clearInterval(hdeskWizardState.cooldownInterval);
        hdeskWizardState.cooldownInterval = null;
    }
    var mainPwd = document.getElementById('odooInpPassword');
    if (mainPwd) {
        mainPwd.value = '';
    }
    try { sessionStorage.removeItem('hdesk_reset_token'); } catch(e){}
    var hiddenToken = document.getElementById('hdeskWizardResetToken');
    if (hiddenToken) hiddenToken.value = '';
}

function handleWizardUserTypeChange() {
    var sel = document.getElementById('hdeskWizardUserType');
    if (sel) hdeskWizardState.userType = sel.value;
}

function handleWizardEmailInput() {
    var inp = document.getElementById('hdeskWizardEmail');
    var btn = document.getElementById('hdeskWizardEmailClear');
    if (!inp || !btn) return;
    if (inp.value && inp.value.length > 0) {
        btn.classList.remove('d-none');
    } else {
        btn.classList.add('d-none');
    }
}

function clearWizardEmail() {
    var inp = document.getElementById('hdeskWizardEmail');
    if (inp) {
        inp.value = '';
        inp.focus();
    }
    handleWizardEmailInput();
}

function wizardChangeEmail() {
    wizardSetStep(1);
}

function wizardPreviousToStep2() {
    wizardSetStep(2);
}

function wizardStartCooldown(seconds) {
    var btn = document.getElementById('btnWizardResendOtp');
    if (!btn) return;
    hdeskWizardState.cooldownSeconds = seconds || 45;
    btn.disabled = true;
    btn.textContent = 'Resend in ' + hdeskWizardState.cooldownSeconds + 's';

    if (hdeskWizardState.cooldownInterval) clearInterval(hdeskWizardState.cooldownInterval);
    hdeskWizardState.cooldownInterval = setInterval(function() {
        hdeskWizardState.cooldownSeconds--;
        if (hdeskWizardState.cooldownSeconds <= 0) {
            clearInterval(hdeskWizardState.cooldownInterval);
            hdeskWizardState.cooldownInterval = null;
            btn.disabled = false;
            btn.textContent = 'Resend OTP';
        } else {
            btn.textContent = 'Resend in ' + hdeskWizardState.cooldownSeconds + 's';
        }
    }, 1000);
}

function handleWizardStep1Submit(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (e && e.stopPropagation) e.stopPropagation();
    var emailInp = document.getElementById('hdeskWizardEmail');
    var userTypeSelect = document.getElementById('hdeskWizardUserType');
    var btn = document.getElementById('btnWizardSendOtp');

    var email = (emailInp ? emailInp.value.trim() : '');
    var userType = (userTypeSelect ? userTypeSelect.value : 'customer');

    if (!email) {
        wizardShowAlert('Please enter your email address.', true);
        return;
    }

    if (btn) btn.disabled = true;
    wizardClearAlert();

    fetch('/helpdesk/auth/password/send_otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            jsonrpc: '2.0',
            params: { email: email, user_type: userType }
        })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
        if (btn) btn.disabled = false;
        var res = data && (data.result || data);
        if (res && res.success) {
            hdeskWizardState.email = res.email || email;
            hdeskWizardState.userType = res.user_type || userType;
            wizardSetStep(2);
            wizardShowAlert(res.message || 'Verification code sent to your email.', false);
            wizardStartCooldown(res.cooldown || 45);
        } else {
            var errMsg = (res && res.message) || (data && data.error && ((data.error.data && data.error.data.message) || data.error.message)) || 'Failed to send verification code. Please check your details.';
            if (errMsg === 'Odoo Server Error') {
                errMsg = 'Unable to send verification code at this time. Please check your account details or contact support.';
            }
            wizardShowAlert(errMsg, true);
        }
    })
    .catch(function(err) {
        if (btn) btn.disabled = false;
        wizardShowAlert('Network connection error. Please try again.', true);
    });
}

function handleWizardResendOtp() {
    var btn = document.getElementById('btnWizardResendOtp');
    if (btn && btn.disabled) return;
    if (btn) btn.disabled = true;
    wizardClearAlert();

    fetch('/helpdesk/auth/password/send_otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            jsonrpc: '2.0',
            params: { email: hdeskWizardState.email, user_type: hdeskWizardState.userType }
        })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
        var res = data && (data.result || data);
        if (res && res.success) {
            wizardShowAlert(res.message || 'New verification code sent to your email.', false);
            wizardStartCooldown(res.cooldown || 45);
            var digits = document.querySelectorAll('.hdesk-otp-digit');
            digits.forEach(function(d) { d.value = ''; d.classList.remove('has-val'); });
            if (digits[0]) digits[0].focus();
        } else {
            if (btn) btn.disabled = false;
            var errMsg = (res && res.message) || (data && data.error && ((data.error.data && data.error.data.message) || data.error.message)) || 'Could not resend code. Please try again.';
            if (errMsg === 'Odoo Server Error') {
                errMsg = 'Unable to resend code at this time. Please try again later.';
            }
            wizardShowAlert(errMsg, true);
        }
    })
    .catch(function(err) {
        if (btn) btn.disabled = false;
        wizardShowAlert('Network error while resending verification code.', true);
    });
}

function handleWizardStep2Submit(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (e && e.stopPropagation) e.stopPropagation();
    var digits = document.querySelectorAll('.hdesk-otp-digit');
    var otp = '';
    digits.forEach(function(d) { otp += (d.value || '').trim(); });

    if (otp.length !== 6) {
        wizardShowAlert('Please enter the complete 6-digit verification code.', true);
        return false;
    }

    var btn = document.getElementById('btnWizardConfirmOtp');
    if (btn) btn.disabled = true;
    wizardClearAlert();

    fetch('/helpdesk/auth/password/verify_otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            jsonrpc: '2.0',
            params: {
                email: hdeskWizardState.email,
                user_type: hdeskWizardState.userType,
                otp: otp
            }
        })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
        if (btn) btn.disabled = false;
        var res = data && (data.result !== undefined ? data.result : data);
        if (res && res.success) {
            var tok = (res.reset_token || '').trim();
            hdeskWizardState.resetToken = tok;
            var hiddenTok = document.getElementById('hdeskWizardResetToken');
            if (hiddenTok) hiddenTok.value = tok;
            try { sessionStorage.setItem('hdesk_reset_token', tok); } catch(err){}
            wizardSetStep(3);
            wizardShowAlert('Code verified! Now create your new password.', false);
        } else {
            var errMsg = (res && res.message) || (data && data.error && ((data.error.data && data.error.data.message) || data.error.message)) || 'Invalid or expired verification code.';
            wizardShowAlert(errMsg, true);
        }
    })
    .catch(function(err) {
        if (btn) btn.disabled = false;
        wizardShowAlert('Network error while verifying code. Please try again.', true);
    });
    return false;
}

function handleWizardStep3Submit(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (e && e.stopPropagation) e.stopPropagation();
    var newPwd = document.getElementById('hdeskWizardNewPwd');
    var confPwd = document.getElementById('hdeskWizardConfirmPwd');
    var btn = document.getElementById('btnWizardUpdatePwd');

    var p1 = (newPwd ? newPwd.value : '').trim();
    var p2 = (confPwd ? confPwd.value : '').trim();

    if (!p1 || !p2) {
        wizardShowAlert('Please fill in both password fields.', true);
        return false;
    }
    if (p1 !== p2) {
        wizardShowAlert('The new password and confirmation password do not match.', true);
        return false;
    }
    if (p1.length < 8) {
        wizardShowAlert('Password must be at least 8 characters long.', true);
        return false;
    }
    if (!(/[A-Za-z]/.test(p1) && /[0-9!@#$%^&*(),.?":{}|<>]/.test(p1))) {
        wizardShowAlert('Password must contain a mix of letters and numbers or symbols.', true);
        return false;
    }

    var origBtnText = btn ? btn.textContent : 'Update Password';
    if (btn) {
        btn.disabled = true;
        btn.textContent = 'Updating...';
    }
    wizardClearAlert();

    var emailVal = (hdeskWizardState.email || '').trim();
    var userTypeVal = (hdeskWizardState.userType || 'customer').trim().toLowerCase();
    var hiddenTok = document.getElementById('hdeskWizardResetToken');
    var resetTokenVal = (hdeskWizardState.resetToken || (hiddenTok ? hiddenTok.value : '') || '').trim();
    if (!resetTokenVal) {
        try { resetTokenVal = (sessionStorage.getItem('hdesk_reset_token') || '').trim(); } catch(err){}
    }

    fetch('/helpdesk/auth/password/reset', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            jsonrpc: '2.0',
            params: {
                email: emailVal,
                user_type: userTypeVal,
                reset_token: resetTokenVal,
                new_password: p1,
                confirm_password: p2
            }
        })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
        if (btn) {
            btn.disabled = false;
            btn.textContent = origBtnText;
        }
        var res = data && (data.result !== undefined ? data.result : data);
        if (res && res.success) {
            wizardShowAlert(res.message || 'Password updated successfully! Returning to login...', false);
            var loginEmail = document.getElementById('odooInpEmail');
            var loginType = document.getElementById('portalTypeSelect');
            var mainUserType = document.getElementById('odooPortalType');
            if (loginEmail) loginEmail.value = emailVal;
            if (loginType) loginType.value = userTypeVal;
            if (mainUserType) mainUserType.value = userTypeVal;
            setTimeout(function() {
                closeForgotModal();
                var loginPwd = document.getElementById('odooInpPassword');
                if (loginPwd) {
                    loginPwd.value = '';
                    loginPwd.focus();
                }
            }, 1800);
        } else {
            var errMsg = (res && res.message) || (data && data.error && ((data.error.data && data.error.data.message) || data.error.message)) || 'Failed to update password. Please try again.';
            wizardShowAlert(errMsg, true);
        }
    })
    .catch(function(err) {
        if (btn) {
            btn.disabled = false;
            btn.textContent = origBtnText;
        }
        wizardShowAlert('Network error while updating password. Please try again.', true);
    });
    return false;
}

function toggleWizardPwd(inputId, btn) {
    var inp = document.getElementById(inputId);
    if (!inp) return;
    var isPwd = inp.type === 'password';
    inp.type = isPwd ? 'text' : 'password';
    var openEye = btn.querySelector('.icon-eye-open');
    var closedEye = btn.querySelector('.icon-eye-closed');
    if (openEye && closedEye) {
        openEye.style.display = isPwd ? 'block' : 'none';
        closedEye.style.display = isPwd ? 'none' : 'block';
    }
}

// OTP Grid Keyboard and Paste Handlers
document.addEventListener('DOMContentLoaded', function() {
    var otpInputs = document.querySelectorAll('.hdesk-otp-digit');
    otpInputs.forEach(function(input, idx) {
        input.addEventListener('input', function(e) {
            var val = input.value.replace(/[^0-9]/g, '');
            input.value = val ? val[0] : '';
            if (input.value) {
                input.classList.add('has-val');
                if (idx < otpInputs.length - 1) {
                    otpInputs[idx + 1].focus();
                }
            } else {
                input.classList.remove('has-val');
            }
        });

        input.addEventListener('keydown', function(e) {
            if (e.key === 'Backspace' && !input.value && idx > 0) {
                otpInputs[idx - 1].focus();
            }
        });

        input.addEventListener('paste', function(e) {
            e.preventDefault();
            var pasteData = (e.clipboardData || window.clipboardData).getData('text') || '';
            var digitsOnly = pasteData.replace(/[^0-9]/g, '').slice(0, 6);
            if (!digitsOnly) return;
            digitsOnly.split('').forEach(function(digit, dIdx) {
                if (otpInputs[dIdx]) {
                    otpInputs[dIdx].value = digit;
                    otpInputs[dIdx].classList.add('has-val');
                }
            });
            var focusTarget = Math.min(digitsOnly.length, 5);
            otpInputs[focusTarget].focus();
        });
    });
});

function handleBackdropClick(e, modalId) {
    if (e.target.id === modalId) {
        var modal = document.getElementById(modalId);
        if (modal) modal.classList.add('d-none');
    }
}

document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
        closeInfoModal();
        closeForgotModal();
    }
});

template.script:
function switchViewType(type, btn) {
    document.querySelectorAll('.view-mode-btn').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');

    const k = document.getElementById('containerKanbanView');
    const l = document.getElementById('containerListView');
    const g = document.getElementById('containerGraphView');
    const a = document.getElementById('containerActivityView');

    if (k) k.style.display = (type === 'kanban' ? 'grid' : 'none');
    if (l) l.style.display = (type === 'list' ? 'block' : 'none');
    if (g) g.style.display = (type === 'graph' ? 'block' : 'none');
    if (a) a.style.display = (type === 'activity' ? 'block' : 'none');
}

function handleMultiViewSearch(query) {
    const q = (query || '').toLowerCase().trim();
    const cards = document.querySelectorAll('.kanban-ticket-card');
    cards.forEach(c => {
        const text = c.innerText.toLowerCase();
        c.style.display = (!q || text.includes(q)) ? 'block' : 'none';
    });
    const rows = document.querySelectorAll('.ticket-list-table tbody tr');
    rows.forEach(r => {
        const text = r.innerText.toLowerCase();
        r.style.display = (!q || text.includes(q)) ? '' : 'none';
    });
}

function openChatOrTicket(ticketId, ticketNum, ticketTitle) {
    const modalEl = document.getElementById('ticketChatModal');
    if (modalEl && window.bootstrap) {
        document.getElementById('modalChatTicketTitle').innerText = ticketTitle + ' (' + ticketNum + ')';
        document.getElementById('modalActiveTicketId').value = ticketId;

        fetch('/helpdesk/chat/messages/' + ticketId)
            .then(r => r.json())
            .then(data => {
                const c = document.getElementById('modalChatContainer');
                c.innerHTML = '';
                (data.messages || []).forEach(m => {
                    const div = document.createElement('div');
                    div.className = 'chat-bubble ' + (m.author_type === 'employee' ? 'bubble-employee' : 'bubble-customer');
                    div.innerHTML = '<strong>' + m.sender_name + ':</strong> ' + m.body;
                    c.appendChild(div);
                });
                c.scrollTop = c.scrollHeight;
            });

        const bsModal = bootstrap.Modal.getOrCreateInstance(modalEl);
        bsModal.show();
    } else {
        window.location.href = '/helpdesk/portal?ticket_id=' + ticketId;
    }
}

function handleModalChatSubmit(e) {
    e.preventDefault();
    const ticketId = document.getElementById('modalActiveTicketId').value;
    const inp = document.getElementById('modalChatMsgInput');
    const text = (inp.value || '').trim();
    if (!text) return;

    const authorType = (window.location.pathname.indexOf('/employee') !== -1) ? 'employee' : 'customer';

    fetch('/helpdesk/chat/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', params: { ticket_id: ticketId, body: text, author_type: authorType } })
    }).then(r => r.json()).then(() => {
        inp.value = '';
        openChatOrTicket(ticketId, '', '');
    });
}

t.script:
                window.toggleCustSidebarSubnav = function(forceState) {
                    var sb = document.getElementById('custAppSidebar') || document.querySelector('.aixo-sidebar');
                    if (!sb) return;
                    var isColl = typeof forceState === 'boolean' ? forceState : !sb.classList.contains('is-collapsed');
                    if (isColl) {
                        sb.classList.add('is-collapsed');
                        document.body.classList.add('sidebar-collapsed');
                        try { localStorage.setItem('cust_sidebar_collapsed', 'true'); } catch(e) {}
                    } else {
                        sb.classList.remove('is-collapsed');
                        document.body.classList.remove('sidebar-collapsed');
                        try { localStorage.setItem('cust_sidebar_collapsed', 'false'); } catch(e) {}
                    }
                    var btn = document.getElementById('btnToggleCustSubnavigation');
                    if (btn) {
                        btn.setAttribute('aria-expanded', isColl ? 'false' : 'true');
                        var arrowKbd = document.getElementById('custToggleKbdArrow');
                        if (arrowKbd) {
                            arrowKbd.innerText = isColl ? 'Right arrow' : 'Left arrow';
                        }
                        btn.setAttribute('title', 'Toggle subnavigation (Ctrl + Shift + ' + (isColl ? 'Right arrow' : 'Left arrow') + ')');
                    }
                };

                function preventSearchInputAutofill() {
                    var searchSelectors = [
                        '#custTopSearchInput', '#searchMultiViewInput', '#projectSearchInput',
                        '#custSearchInp', '#empSearchInput', '#empTopSearchInput', '#pendingSearchInput',
                        'input[type="search"]', 'input[placeholder*="Search"]'
                    ];
                    try {
                        document.querySelectorAll(searchSelectors.join(',')).forEach(function(inp) {
                            if (inp && inp.value && inp.value.indexOf('@') > -1) {
                                inp.value = '';
                                if (inp.id === 'custTopSearchInput' && window.handleAixoGlobalSearch) window.handleAixoGlobalSearch('');
                                if (inp.id === 'projectSearchInput' && window.filterProjectCards) window.filterProjectCards('');
                                if (inp.id === 'custSearchInp' && window.searchCustCards) window.searchCustCards('');
                            }
                        });
                    } catch(e) {}
                }
                setTimeout(preventSearchInputAutofill, 50);
                setTimeout(preventSearchInputAutofill, 200);
                setTimeout(preventSearchInputAutofill, 600);
                setTimeout(preventSearchInputAutofill, 1500);
                window.addEventListener('pageshow', preventSearchInputAutofill);

                document.addEventListener('DOMContentLoaded', function() {
                    preventSearchInputAutofill();
                    try {
                        if (localStorage.getItem('cust_sidebar_collapsed') === 'true' && window.innerWidth >= 768) {
                            var sb = document.getElementById('custAppSidebar');
                            if (sb) {
                                sb.classList.add('is-collapsed');
                                document.body.classList.add('sidebar-collapsed');
                                var btn = document.getElementById('btnToggleCustSubnavigation');
                                if (btn) {
                                    btn.setAttribute('aria-expanded', 'false');
                                    var arrowKbd = document.getElementById('custToggleKbdArrow');
                                    if (arrowKbd) arrowKbd.innerText = 'Right arrow';
                                }
                            }
                        }
                    } catch(e) {}
                    var initId = document.getElementById('urlParamTicketId') ? document.getElementById('urlParamTicketId').value : '';
                    if (initId) {
                        openAixoDetail(initId);
                    } else {
                        var activeId = document.getElementById('initialActiveTicketId') ? document.getElementById('initialActiveTicketId').value : '';
                        if (activeId) {
                            window.currentActiveTicket = { id: activeId };
                        }
                    }
                });

                window.portalStageMaps = ;

                function openCustTicketsStageMap(smId) {
                    if (typeof switchAixoTab === 'function') {
                        switchAixoTab('tickets');
                    }
                    filterCustTicketsByStageMap(smId);
                }
                window.openCustTicketsStageMap = openCustTicketsStageMap;

                function filterCustTicketsByStageMap(smId, btnEl) {
                    var targetId = smId || 'all';

                    // 1. Highlight clicked tab, un-highlight others
                    document.querySelectorAll('.cust-stage-filter-btn').forEach(function(btn) {
                        btn.classList.remove('active');
                        btn.style.border = '1px solid #dce5f2';
                        btn.style.color = '#172033';
                        btn.style.background = '#ffffff';
                        btn.style.fontWeight = '600';
                    });

                    var activeBtn = btnEl || document.getElementById('ticketStageTab_' + targetId);
                    if (!activeBtn) {
                        activeBtn = document.querySelector('.cust-stage-filter-btn[data-stage-id="' + targetId + '"]') ||
                                    document.querySelector('.cust-stage-filter-btn[data-stage-code="' + targetId + '"]');
                    }
                    if (activeBtn) {
                        activeBtn.classList.add('active');
                        if (targetId === 'all') {
                            activeBtn.style.border = '1px solid #2563eb';
                            activeBtn.style.color = '#ffffff';
                            activeBtn.style.background = '#2563eb';
                            activeBtn.style.fontWeight = '700';
                        } else {
                            activeBtn.style.border = '1px solid #2563eb';
                            activeBtn.style.color = '#1e40af';
                            activeBtn.style.background = '#eff6ff';
                            activeBtn.style.fontWeight = '700';
                        }
                    }

                    // 2. Resolve matching ticket IDs from stage map
                    var smList = window.portalStageMaps || [];
                    var matchedSm = null;
                    if (targetId !== 'all') {
                        for (var i = 0; i < smList.length; i++) {
                            if (String(smList[i].id) === String(targetId) || String(smList[i].code) === String(targetId)) {
                                matchedSm = smList[i];
                                break;
                            }
                        }
                    }

                    // 3. Filter rows in #tableAllTickets
                    var rows = document.querySelectorAll('#tableAllTickets tbody tr.cust-ticket-row');
                    var visibleCount = 0;
                    rows.forEach(function(row) {
                        var tId = parseInt(row.getAttribute('data-ticket-id'), 10);
                        var rStage = (row.getAttribute('data-stage') || '').toLowerCase().trim();
                        var rStageName = (row.getAttribute('data-stage-name') || '').toLowerCase().trim();
                        var show = false;

                        if (targetId === 'all') {
                            show = true;
                        } else if (matchedSm) {
                            var tIds = matchedSm.ticket_ids || [];
                            if (tIds.indexOf(tId) > -1) {
                                show = true;
                            } else if (matchedSm.stage_keys && matchedSm.stage_keys.length > 0) {
                                var sKeys = matchedSm.stage_keys.map(function(k) { return k.toLowerCase().replace(/[\s_-]/g, ''); });
                                var normStage = rStage.replace(/[\s_-]/g, '');
                                var normStageName = rStageName.replace(/[\s_-]/g, '');
                                if (sKeys.indexOf(normStage) > -1 || sKeys.indexOf(normStageName) > -1) {
                                    show = true;
                                }
                            }
                        } else {
                            var tCode = String(targetId).toLowerCase().replace(/[\s_-]/g, '');
                            var normStage = rStage.replace(/[\s_-]/g, '');
                            if (normStage === tCode || rStageName === tCode) {
                                show = true;
                            }
                        }

                        if (show) {
                            row.style.display = '';
                            visibleCount++;
                        } else {
                            row.style.display = 'none';
                        }
                    });

                    // 4. Update empty message and counter
                    var noRow = document.getElementById('noCustTicketsRow');
                    if (noRow) {
                        noRow.style.display = (visibleCount === 0) ? '' : 'none';
                    }
                    var countLbl = document.getElementById('custTicketCountLabel');
                    if (countLbl) {
                        if (targetId === 'all') {
                            countLbl.textContent = 'Showing all ' + visibleCount + ' stored tickets';
                        } else {
                            var stageTitle = matchedSm ? matchedSm.name : targetId;
                            countLbl.textContent = 'Showing ' + visibleCount + ' tickets for "' + stageTitle + '"';
                        }
                    }
                }
                window.filterCustTicketsByStageMap = filterCustTicketsByStageMap;
                window.switchTicketListStage = filterCustTicketsByStageMap;

                function filterTicketRows(query, tableId) {
                    var table = document.getElementById(tableId);
                    if (!table) return;
                    var q = (query || '').toLowerCase().trim();
                    var rows = table.querySelectorAll('tbody tr');
                    rows.forEach(function(row) {
                        var text = row.innerText.toLowerCase();
                        row.style.display = (!q || text.indexOf(q) > -1) ? '' : 'none';
                    });
                }


                // Global Minimalist Profile Photo Lightbox Helpers
                window.openProfilePhotoLightbox = function(url) {
                    if (!url || url === '#' || url.indexOf('undefined') !== -1) return;
                    var lb = document.getElementById('profilePhotoLightbox');
                    var img = document.getElementById('profileLightboxImageTag');
                    if (!lb || !img) {
                        window.open(url, '_blank');
                        return;
                    }
                    img.src = url;
                    lb.style.display = 'flex';
                    document.body.style.overflow = 'hidden';
                };

                window.closeProfilePhotoLightbox = function() {
                    var lb = document.getElementById('profilePhotoLightbox');
                    if (lb) lb.style.display = 'none';
                    var img = document.getElementById('profileLightboxImageTag');
                    if (img) img.src = '';
                    document.body.style.overflow = '';
                };

                // ESC key handler for customer lightboxes and modals
                document.addEventListener('keydown', function(e) {
                    if (e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) {
                        if (typeof window.closeProfilePhotoLightbox === 'function') {
                            window.closeProfilePhotoLightbox();
                        }
                        if (typeof window.closeSameScreenImageModal === 'function') {
                            window.closeSameScreenImageModal();
                        }
                    }
                });

                // Global Same-Screen Image Lightbox and Direct File Download Helpers
                window.openSameScreenImageModal = function(url, title) {
                    var lb = document.getElementById('sameScreenImageLightbox');
                    var img = document.getElementById('sameScreenImageTag');
                    var ttl = document.getElementById('sameScreenImageTitle');
                    var dl = document.getElementById('sameScreenImageDownloadBtn');
                    if (!url || url === '#' || url.indexOf('undefined') !== -1) return;
                    var viewUrl = url;
                    if (viewUrl.indexOf('/web/content/') !== -1) {
                        var mId = viewUrl.match(/\/web\/content\/(\d+)/);
                        if (mId) viewUrl = '/helpdesk/attachment/view/' + mId[1];
                    }
                    if (!lb || !img) {
                        window.open(viewUrl, '_blank');
                        return;
                    }
                    img.src = viewUrl;
                    if (ttl) ttl.innerText = title || 'Image Preview';
                    if (dl) {
                        var dlUrl = viewUrl.replace('/view/', '/download/');
                        dl.onclick = function(e) {
                            e.preventDefault();
                            downloadAttachmentDirect(dlUrl, title || 'image.png');
                        };
                    }
                    lb.style.display = 'flex';
                };

                window.closeSameScreenImageModal = function() {
                    var lb = document.getElementById('sameScreenImageLightbox');
                    if (lb) lb.style.display = 'none';
                };

                window.downloadAttachmentDirect = function(url, filename) {
                    if (!url || url === '#' || url.indexOf('undefined') !== -1) return;
                    var dlUrl = url;
                    if (dlUrl.indexOf('/web/content/') !== -1) {
                        var mId = dlUrl.match(/\/web\/content\/(\d+)/);
                        if (mId) dlUrl = '/helpdesk/attachment/download/' + mId[1];
                    } else if (dlUrl.indexOf('/helpdesk/attachment/view/') !== -1) {
                        dlUrl = dlUrl.replace('/view/', '/download/');
                    }
                    var a = document.createElement('a');
                    a.href = dlUrl;
                    if (filename) a.download = filename;
                    document.body.appendChild(a);
                    a.click();
                    setTimeout(function() {
                        if (a.parentNode) a.parentNode.removeChild(a);
                    }, 200);
                };
                // Customer Portal Screenshot 3 Attachment and Emoji Helpers
                window.selectedAixoReplyFile = null;
                function onAixoReplyFileSelected(input) {
                    if (input.files && input.files[0]) {
                        window.selectedAixoReplyFile = input.files[0];
                        var bar = document.getElementById('aixoReplyPreviewBar');
                        var nameEl = document.getElementById('aixoReplyFileName');
                        if (nameEl) nameEl.innerText = input.files[0].name;
                        if (bar) bar.style.display = 'flex';
                    }
                }
                function clearAixoReplyAttachment() {
                    window.selectedAixoReplyFile = null;
                    var bar = document.getElementById('aixoReplyPreviewBar');
                    if (bar) bar.style.display = 'none';
                    var inp = document.getElementById('aixoReplyFileInput');
                    if (inp) inp.value = '';
                    var imgInp = document.getElementById('aixoReplyImageInput');
                    if (imgInp) imgInp.value = '';
                    var vidInp = document.getElementById('aixoReplyVideoInput');
                    if (vidInp) vidInp.value = '';
                }

                // Modern WhatsApp Emoji Dataset for Customer Portal
                window.aixoEmojiData = {
                    smileys: [
                        { e: '😀', n: 'Grinning Face' }, { e: '😃', n: 'Grinning Face with Big Eyes' }, { e: '😄', n: 'Grinning Face with Smiling Eyes' },
                        { e: '😁', n: 'Beaming Face' }, { e: '😆', n: 'Grinning Squinting Face' }, { e: '😅', n: 'Grinning Face with Sweat' },
