                window.currentAixoEmojiCategory = 'smileys';
                window.currentAixoEmojiList = [];

                function initAixoEmojiGridDelegation() {
                    var grid = document.getElementById('aixoEmojiGrid');
                    if (!grid || grid.dataset.delegated) return;
                    grid.dataset.delegated = 'true';
                    grid.addEventListener('click', function(e) {
                        var itemEl = e.target.closest('.aixo-emoji-item');
                        if (!itemEl) return;
                        var idx = parseInt(itemEl.getAttribute('data-idx') || -1);
                        var list = window.currentAixoEmojiList || [];
                        if (list[idx]) insertAixoEmoji(list[idx].e);
                    });
                    grid.addEventListener('mouseover', function(e) {
                        var itemEl = e.target.closest('.aixo-emoji-item');
                        if (!itemEl) return;
                        var idx = parseInt(itemEl.getAttribute('data-idx') || -1);
                        var list = window.currentAixoEmojiList || [];
                        if (list[idx]) updateAixoEmojiPreview(list[idx].e, list[idx].n);
                    });
                }

                function renderAixoEmojiGrid(emojis) {
                    var grid = document.getElementById('aixoEmojiGrid');
                    if (!grid) return;
                    initAixoEmojiGridDelegation();
                    window.currentAixoEmojiList = emojis;
                    grid.innerHTML = (emojis || []).map(function(item, idx) {
                        return '<span class="aixo-emoji-item" data-idx="' + idx + '" style="font-size: 22px; width: 36px; height: 36px; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; border-radius: 8px; user-select: none;">' + item.e + '</span>';
                    }).join('');
                }

                function toggleAixoEmojiPicker(e) {
                    if (e) e.stopPropagation();
                    var p = document.getElementById('aixoEmojiPicker');
                    if (!p) return;
                    if (p.style.display === 'block') {
                        p.style.display = 'none';
                    } else {
                        p.style.display = 'block';
                        var list = (window.aixoEmojiData && window.aixoEmojiData[window.currentAixoEmojiCategory || 'smileys']) || (window.aixoEmojiData ? window.aixoEmojiData.smileys : []);
                        renderAixoEmojiGrid(list);
                        var search = document.getElementById('aixoEmojiSearchInput');
                        if (search) setTimeout(function() { search.focus(); }, 50);
                    }
                }

                function insertAixoEmoji(emoji) {
                    var inp = document.getElementById('aixoReplyInput');
                    if (!inp) return;
                    inp.value = (inp.value || '') + emoji;
                    inp.focus();
                }

                function updateAixoEmojiPreview(char, name) {
                    var c = document.getElementById('aixoEmojiPreviewChar');
                    var n = document.getElementById('aixoEmojiPreviewName');
                    if (c) c.innerText = char;
                    if (n) n.innerText = name;
                }

                function switchAixoEmojiCat(catKey, btn) {
                    window.currentAixoEmojiCategory = catKey;
                    var buttons = document.querySelectorAll('.aixo-emoji-cat-btn');
                    buttons.forEach(function(b) { b.style.borderBottomColor = 'transparent'; });
                    if (btn) btn.style.borderBottomColor = '#2563EB';
                    var searchInput = document.getElementById('aixoEmojiSearchInput');
                    if (searchInput) searchInput.value = '';
                    var list = (window.aixoEmojiData && window.aixoEmojiData[catKey]) || [];
                    renderAixoEmojiGrid(list);
                }

                function filterAixoEmojis(query) {
                    var q = (query || '').toLowerCase().trim();
                    if (!q) {
                        var list = (window.aixoEmojiData && window.aixoEmojiData[window.currentAixoEmojiCategory || 'smileys']) || [];
                        renderAixoEmojiGrid(list);
                        return;
                    }
                    var all = [];
                    if (window.aixoEmojiData) {
                        Object.keys(window.aixoEmojiData).forEach(function(k) {
                            (window.aixoEmojiData[k] || []).forEach(function(item) {
                                if (item.n.toLowerCase().indexOf(q) !== -1 || item.e.indexOf(q) !== -1) {
                                    if (!all.find(function(x) { return x.e === item.e; })) all.push(item);
                                }
                            });
                        });
                    }
                    renderAixoEmojiGrid(all);
                }

                document.addEventListener('click', function(e) {
                    var picker = document.getElementById('aixoEmojiPicker');
                    var btn = document.getElementById('aixoEmojiBtn');
                    if (picker && picker.style.display === 'block') {
                        if (!picker.contains(e.target) && (!btn || !btn.contains(e.target))) {
                            picker.style.display = 'none';
                        }
                    }
                });


                document.addEventListener('keydown', function(e) {
                    if (e.key === 'Escape') {
                        if (window.closeSameScreenImageModal) window.closeSameScreenImageModal();
                        if (window.closeCustHelpSupportModal) window.closeCustHelpSupportModal();
                    }
                });

                window.openCustHelpSupportModal = function() {
                    var m = document.getElementById('custHelpSupportModal');
                    if (m) {
                        m.style.display = 'flex';
                    }
                };
                window.closeCustHelpSupportModal = function() {
                    var m = document.getElementById('custHelpSupportModal');
                    if (m) {
                        m.style.display = 'none';
                    }
                };

                function switchAixoTab(tabKey) {
                    if (tabKey === 'help') {
                        openCustHelpSupportModal();
                        return;
                    }
                    try {
                        localStorage.setItem('helpdesk_cust_active_tab', tabKey);
                        if (tabKey !== 'ticket_detail') {
                            localStorage.removeItem('helpdesk_cust_active_ticket_id');
                        }
                        if (window.history && window.history.replaceState) {
                            window.history.replaceState(null, '', '#' + tabKey);
                        } else {
                            window.location.hash = '#' + tabKey;
                        }
                    } catch(e) {}

                    document.querySelectorAll('.aixo-screen-view').forEach(s => s.classList.remove('active'));
                    document.querySelectorAll('.aixo-nav-btn').forEach(b => b.classList.remove('active'));
                    if (document.getElementById('custProfilePopover')) document.getElementById('custProfilePopover').style.display = 'none';

                    if (tabKey === 'dashboard') {
                        document.getElementById('scrDashboard').classList.add('active');
                        var navDash = document.getElementById('navAixoDashboard');
                        if (navDash) navDash.classList.add('active');
                    } else if (tabKey === 'tickets') {
                        document.getElementById('scrTickets').classList.add('active');
                        var navTkt = document.getElementById('navAixoTickets');
                        if (navTkt) navTkt.classList.add('active');
                    } else if (tabKey === 'projects') {
                        document.getElementById('scrProjects').classList.add('active');
                        var navProj = document.getElementById('navAixoProjects');
                        if (navProj) navProj.classList.add('active');
                        if (typeof backToProjectsList === 'function') {
                            backToProjectsList();
                        }
                    } else if (tabKey === 'discussions') {
                        document.getElementById('scrDiscussions').classList.add('active');
                        var navDisc = document.getElementById('navAixoDiscussions');
                        if (navDisc) navDisc.classList.add('active');
                    } else if (tabKey === 'knowledge') {
                        document.getElementById('scrKnowledge').classList.add('active');
                        var navHelp = document.getElementById('navAixoHelp');
                        if (navHelp) navHelp.classList.add('active');
                    } else if (tabKey === 'profile') {
                        document.getElementById('scrProfile').classList.add('active');
                        var navComp = document.getElementById('navAixoCompany');
                        if (navComp) navComp.classList.add('active');
                    } else if (tabKey === 'create_ticket') {
                        document.getElementById('scrCreateTicket').classList.add('active');
                        var navTickets = document.getElementById('navAixoTickets');
                        if (navTickets) navTickets.classList.add('active');
                    }
                    window.scrollTo(0, 0);
                }

                function switchProjTab(tabKey) {
                    var tabs = ['overview', 'tickets', 'documents', 'team', 'discussions', 'milestones'];
                    tabs.forEach(function(t) {
                        var pane = document.getElementById('projPane_' + t);
                        var btn = document.getElementById('projTabBtn_' + t);
                        if (pane) {
                            pane.style.display = (t === tabKey) ? 'block' : 'none';
                        }
                        if (btn) {
                            if (t === tabKey) {
                                btn.style.color = '#0f172a';
                                btn.style.fontWeight = '700';
                                btn.style.borderBottom = '2px solid #0f172a';
                            } else {
                                btn.style.color = '#64748b';
                                btn.style.fontWeight = '500';
                                btn.style.borderBottom = '2px solid transparent';
                            }
                        }
                    });
                }

                function openProjectDetailView(proj) {
                    if (!proj) return;
                    try {
                        localStorage.setItem('helpdesk_cust_project_detail_open', '1');
                        if (proj.id) localStorage.setItem('helpdesk_cust_active_project_id', String(proj.id));
                        if (window.history && window.history.replaceState) {
                            window.history.replaceState(null, '', '#project_' + (proj.id || 'detail'));
                        } else {
                            window.location.hash = '#project_' + (proj.id || 'detail');
                        }
                    } catch(e) {}
                    var listCont = document.getElementById('projectsListContainer');
                    var detailCont = document.getElementById('projectDetailContainer');
                    if (listCont) {
                        if (detailCont) {
                            listCont.style.display = 'none';
                            detailCont.style.display = 'block';
                        }
                    }

                    var initialsEl = document.getElementById('projDetailInitials');
                    var avatarEl = document.getElementById('projDetailAvatar');
                    var titleEl = document.getElementById('projDetailTitle');
                    var statusEl = document.getElementById('projDetailStatus');
                    var overviewStatusEl = document.getElementById('projOverviewStatus');
                    var descEl = document.getElementById('projDetailDesc');
                    var openCountEl = document.getElementById('projDetailOpenCount');
                    var overdueCountEl = document.getElementById('projDetailOverdueCount');
                    var teamCountEl = document.getElementById('projDetailTeamCount');
                    var progressValEl = document.getElementById('projDetailProgressVal');
                    var progressBarEl = document.getElementById('projDetailProgressBar');
                    var overviewNameEl = document.getElementById('projOverviewName');
                    var overviewDescEl = document.getElementById('projOverviewDesc');
                    var overviewStartDateEl = document.getElementById('projOverviewStartDate');
                    var overviewEndDateEl = document.getElementById('projOverviewEndDate');
                    var overviewPriorityEl = document.getElementById('projOverviewPriority');
                    var overviewOwnerEl = document.getElementById('projOverviewOwner');
                    var donutCircle = document.getElementById('projDonutCircle');
                    var donutText = document.getElementById('projDonutText');
                    var donutCompleted = document.getElementById('projDonutLegendCompleted');
                    var donutInProgress = document.getElementById('projDonutLegendInProgress');
                    var donutNotStarted = document.getElementById('projDonutLegendNotStarted');
                    var donutQuickInfo = document.getElementById('projDonutQuickInfo');

                    if (initialsEl) {
                        initialsEl.innerText = proj.initials || 'PR';
                    }
                    if (avatarEl) {
                        if (proj.bg) avatarEl.style.background = proj.bg;
                        if (proj.color) avatarEl.style.color = proj.color;
                    }
                    if (titleEl) {
                        titleEl.innerText = proj.name || 'Project Overview';
                    }
                    if (overviewNameEl) {
                        overviewNameEl.innerText = proj.name || 'Project Overview';
                    }
                    var pDesc = proj.description || proj.desc || 'Project synchronized with Odoo.';
                    if (descEl) {
                        descEl.innerText = pDesc;
                    }
                    if (overviewDescEl) {
                        overviewDescEl.innerText = pDesc;
                    }
                    if (overviewStartDateEl) {
                        overviewStartDateEl.innerText = proj.start_date || '-';
                    }
                    if (overviewEndDateEl) {
                        overviewEndDateEl.innerText = proj.end_date || '-';
                    }
                    if (overviewPriorityEl) {
                        overviewPriorityEl.innerText = proj.priority || 'Medium';
                    }
                    if (overviewOwnerEl) {
                        overviewOwnerEl.innerText = proj.manager_name || proj.owner || '-';
                    }

                    var status = proj.status || 'Active';
                    var isCompleted = (status.toLowerCase() === 'completed');

                    if (statusEl) {
                        statusEl.innerText = status;
                        if (isCompleted) {
                            statusEl.className = 'badge-aixo pill-in-progress-yellow';
                            statusEl.style.background = '#dbeafe';
                            statusEl.style.color = '#2563eb';
                        } else {
                            statusEl.className = 'badge-aixo pill-active-green';
                            statusEl.style.background = '#dcfce7';
                            statusEl.style.color = '#10b981';
                        }
                    }
                    if (overviewStatusEl) {
                        overviewStatusEl.innerText = status;
                        if (isCompleted) {
                            overviewStatusEl.className = 'badge-aixo pill-in-progress-yellow';
                            overviewStatusEl.style.background = '#dbeafe';
                            overviewStatusEl.style.color = '#2563eb';
                        } else {
                            overviewStatusEl.className = 'badge-aixo pill-active-green';
                            overviewStatusEl.style.background = '#dcfce7';
                            overviewStatusEl.style.color = '#10b981';
                        }
                    }

                    var openCnt = (proj.open_count !== undefined) ? proj.open_count : (proj.openCount !== undefined ? proj.openCount : 0);
                    var overdueCnt = (proj.overdue_count !== undefined) ? proj.overdue_count : (proj.overdueCount !== undefined ? proj.overdueCount : 0);
                    var teamCnt = (proj.team_count !== undefined) ? proj.team_count : (proj.teamCount !== undefined ? proj.teamCount : (proj.team_members ? proj.team_members.length : 0));

                    if (openCountEl) openCountEl.innerText = openCnt;
                    if (overdueCountEl) overdueCountEl.innerText = overdueCnt;
                    if (teamCountEl) teamCountEl.innerText = teamCnt;

                    var progress = (proj.progress !== undefined) ? proj.progress : 0;
                    if (progressValEl) progressValEl.innerText = progress + '%';
                    if (progressBarEl) {
                        progressBarEl.style.width = progress + '%';
                        progressBarEl.style.background = isCompleted ? '#16a34a' : '#2563eb';
                    }

                    if (donutCircle) {
                        donutCircle.setAttribute('stroke-dasharray', progress + ', 100');
                        donutCircle.setAttribute('stroke', isCompleted ? '#16a34a' : '#2563eb');
                    }
                    if (donutText) donutText.innerText = progress + '%';
                    if (donutCompleted) donutCompleted.innerText = (proj.progress !== undefined ? proj.progress : progress) + '%';
                    if (donutInProgress) {
                        var inProg = (proj.in_progress_pct !== undefined) ? proj.in_progress_pct : Math.max(0, 100 - progress);
                        donutInProgress.innerText = inProg + '%';
                    }
                    if (donutNotStarted) {
                        var notStarted = (proj.not_started_pct !== undefined) ? proj.not_started_pct : (isCompleted ? 0 : Math.max(0, 100 - progress - (proj.in_progress_pct || 0)));
                        donutNotStarted.innerText = notStarted + '%';
                    }

                    if (donutQuickInfo) {
                        if (isCompleted) {
                            donutQuickInfo.innerText = 'This project has been fully delivered and all milestones have been completed successfully.';
                        } else if (overdueCnt > 0) {
                            donutQuickInfo.innerText = 'This project is in active execution. ' + overdueCnt + ' ticket(s) are overdue and require priority follow-up.';
                        } else {
                            donutQuickInfo.innerText = 'This project is currently running smoothly with zero overdue tickets.';
                        }
                    }

                    // Render dynamic team members
                    var teamMembers = proj.team_members || [];
                    var teamListEl = document.getElementById('projDetailTeamList');
                    var teamGridEl = document.getElementById('projTabTeamGrid');
                    if (teamListEl) {
                        if (teamMembers.length > 0) {
                            teamListEl.innerHTML = teamMembers.map(function(m) {
                                return '
' +
                                    '
' +
                                        '
' + (m.initials || 'TM') + '' +
                                        '
' +
                                            '
' + (m.name || 'Team Member') + '' +
                                            '
' + (m.job || 'Team Member') + '' +
                                        '' +
                                    '' +
                                    '' + (m.online ? 'Online' : 'Offline') + '' +
                                '';
                            }).join('');
                        } else {
                            teamListEl.innerHTML = '
No team members assigned in Odoo.';
                        }
                    }
                    if (teamGridEl) {
                        if (teamMembers.length > 0) {
                            teamGridEl.innerHTML = teamMembers.map(function(m) {
                                return '
