                    // Render dynamic milestones
                    var milestones = proj.milestones || [];
                    var mListEl = document.getElementById('projDetailMilestonesList');
                    var mTabListEl = document.getElementById('projTabMilestonesList');
                    if (mListEl) {
                        if (milestones.length > 0) {
                            mListEl.innerHTML = '
' +
                                milestones.map(function(m) {
                                    var isDone = m.is_reached || (m.status && m.status.toLowerCase() === 'completed');
                                    var iconBg = isDone ? 'background: #16a34a; color: #ffffff;' : 'background: #ffffff; border: 2px solid #cbd5e1;';
                                    var badgeStyle = isDone ? 'background: #dcfce7; color: #15803d;' : 'background: #eff6ff; color: #2563eb;';
                                    return '
' +
                                        '
' + (isDone ? '✓' : '') + '' +
                                        '
' +
                                            '
' + (m.name || 'Milestone') + '' +
                                        '' +
                                        '
' +
                                            '
' + (m.date || '') + '' +
                                            '' + (m.status || 'Pending') + '' +
                                        '' +
                                    '';
                                }).join('');
                        } else {
                            mListEl.innerHTML = '
No milestones configured in Odoo.';
                        }
                    }
                    if (mTabListEl) {
                        if (milestones.length > 0) {
                            mTabListEl.innerHTML = milestones.map(function(m) {
                                var isDone = m.is_reached || (m.status && m.status.toLowerCase() === 'completed');
                                var pct = isDone ? 100 : 50;
                                var barColor = isDone ? '#16a34a' : '#2563eb';
                                return '
' +
                                    '
' +
                                        '' + (m.name || 'Milestone') + '' +
