                    window.scrollTo(0, 0);
                }


                // Customer Project Actions Three-Dot Menu
                function toggleCustProjActionsMenu(btn, e, optId) {
                    if (e && e.stopPropagation) e.stopPropagation();
                    var id = optId || (btn ? btn.getAttribute('data-id') : '');
                    var menu = document.getElementById('custProjActionsMenu_' + id);
                    if (!menu) return;
                    var isOpen = menu.style.display === 'flex' || menu.style.display === 'block';
                    closeAllCustProjActionMenus();
                    if (!isOpen) {
                        menu.style.display = 'flex';
                    }
                }
                window.toggleCustProjActionsMenu = toggleCustProjActionsMenu;

                function closeAllCustProjActionMenus() {
                    document.querySelectorAll('.cust-proj-actions-menu').forEach(function(m) {
                        m.style.display = 'none';
                    });
                }
                window.closeAllCustProjActionMenus = closeAllCustProjActionMenus;

                document.addEventListener('click', function(e) {
                    if (!e.target.closest('.cust-proj-dots-container')) {
                        closeAllCustProjActionMenus();
                    }
                });

                function triggerCustProjView(btn, e) {
                    if (e && e.stopPropagation) e.stopPropagation();
                    closeAllCustProjActionMenus();
                    if (typeof openProjectFromBtn === 'function') {
                        openProjectFromBtn(btn);
                    }
                }
                window.triggerCustProjView = triggerCustProjView;

                function triggerCustProjNewTicket(btn, e) {
                    if (e && e.stopPropagation) e.stopPropagation();
                    closeAllCustProjActionMenus();
                    var pId = btn ? btn.getAttribute('data-id') : '';
                    if (typeof showAixoCreateModal === 'function') {
                        showAixoCreateModal();
                        setTimeout(function() {
                            var sel = document.getElementById('newTicketProject') || document.getElementById('empNewTicketProject');
                            if (sel && pId) sel.value = pId;
                        }, 80);
                    } else if (typeof switchAixoTab === 'function') {
                        switchAixoTab('create_ticket');
                    }
                }
                window.triggerCustProjNewTicket = triggerCustProjNewTicket;

                function triggerCustProjFilterTickets(btn, e) {
                    if (e && e.stopPropagation) e.stopPropagation();
                    closeAllCustProjActionMenus();
                    var pName = btn ? btn.getAttribute('data-name') : '';
                    if (typeof switchAixoTab === 'function') {
                        switchAixoTab('tickets');
                        setTimeout(function() {
                            if (typeof filterCustTicketsByStageMap === 'function') {
                                filterCustTicketsByStageMap('all');
                            }
                            var rows = document.querySelectorAll('#tableAllTickets tbody tr.cust-ticket-row');
                            rows.forEach(function(row) {
                                var projCell = row.children[3];
                                if (projCell) {
                                    var txt = (projCell.textContent || '').trim().toLowerCase();
                                    row.style.display = (!pName || txt.indexOf(pName.toLowerCase()) > -1) ? '' : 'none';
                                }
                            });
                        }, 100);
                    }
                }
                window.triggerCustProjFilterTickets = triggerCustProjFilterTickets;

                function copyCustProjName(btn, e) {
                    if (e && e.stopPropagation) e.stopPropagation();
                    closeAllCustProjActionMenus();
                    var pName = (btn ? btn.getAttribute('data-name') : '') || '';
                    if (navigator.clipboard && navigator.clipboard.writeText) {
                        navigator.clipboard.writeText(pName).then(function() {
                            if (typeof showAixoToast === 'function') showAixoToast('Copied: ' + pName);
                            else alert('Copied project name: ' + pName);
                        });
                    } else {
                        prompt('Copy project name:', pName);
                    }
                }
                window.copyCustProjName = copyCustProjName;

                function openProjectFromBtn(btn) {
                    if (!btn) return;
                    var projId = parseInt(btn.dataset.id, 10);
                    var container = document.getElementById('projectCardsContainer');
                    var projectsData = [];
                    if (container && container.dataset.projects) {
                        try {
                            projectsData = JSON.parse(container.dataset.projects);
                        } catch(e) {
                            console.error('Error parsing projects json:', e);
                        }
                    }
                    var matchedProj = projectsData.find(function(p) { return p.id === projId; });
                    if (!matchedProj) {
                        var d = btn.dataset;
                        matchedProj = {
                            id: d.id,
                            name: d.name,
                            initials: d.initials,
                            status: d.status || 'Active',
                            description: d.desc || '',
                            open_count: parseInt(d.opencount || '0', 10),
                            overdue_count: parseInt(d.overduecount || '0', 10),
                            team_count: parseInt(d.teamcount || '0', 10),
                            progress: parseInt(d.progress || '0', 10),
                            start_date: '-',
                            end_date: '-',
                            priority: 'Medium',
                            manager_name: d.managername || d.owner || '-',
                            owner: d.managername || d.owner || '-',
                            bg: d.bg || '#eff6ff',
                            color: d.color || '#2563eb',
                            team_members: [],
                            recent_tickets: [],
                            milestones: []
                        };
                    }
                    openProjectDetailView(matchedProj);
                }

                function backToProjectsList() {
                    try {
                        localStorage.removeItem('helpdesk_cust_project_detail_open');
                        localStorage.removeItem('helpdesk_cust_active_project_id');
                        if (window.history && window.history.replaceState) {
                            window.history.replaceState(null, '', '#projects');
                        } else {
                            window.location.hash = '#projects';
                        }
                    } catch(e) {}
                    var listCont = document.getElementById('projectsListContainer');
                    var detailCont = document.getElementById('projectDetailContainer');
                    if (listCont) {
                        if (detailCont) {
                            detailCont.style.display = 'none';
                            listCont.style.display = 'block';
                        }
                    }
                    window.scrollTo(0, 0);
                }

                function switchProjectView(mode) {
                    var m = mode || 'kanban';
                    var kanbanCont = document.getElementById('projectsKanbanContainer');
                    var listCont = document.getElementById('projectCardsContainer');
                    var btnKanban = document.getElementById('projectBtnKanbanView');
                    var btnList = document.getElementById('projectBtnListView');

                    if (m === 'kanban') {
                        if (kanbanCont) kanbanCont.style.display = 'grid';
                        if (listCont) listCont.style.display = 'none';
                        if (btnKanban) {
                            btnKanban.style.background = '#2563eb';
                            btnKanban.style.color = '#ffffff';
                            btnKanban.style.boxShadow = '0 1px 2px rgba(0,0,0,0.1)';
                        }
                        if (btnList) {
                            btnList.style.background = 'transparent';
                            btnList.style.color = '#64748b';
                            btnList.style.boxShadow = 'none';
                        }
                    } else {
                        if (kanbanCont) kanbanCont.style.display = 'none';
                        if (listCont) listCont.style.display = 'flex';
                        if (btnList) {
                            btnList.style.background = '#2563eb';
                            btnList.style.color = '#ffffff';
                            btnList.style.boxShadow = '0 1px 2px rgba(0,0,0,0.1)';
                        }
                        if (btnKanban) {
                            btnKanban.style.background = 'transparent';
                            btnKanban.style.color = '#64748b';
                            btnKanban.style.boxShadow = 'none';
                        }
                    }
                    try {
                        localStorage.setItem('aixo_project_view_mode', m);
                    } catch(e) {}
                    updateKanbanCounters();
                }
                window.switchProjectView = switchProjectView;

                function updateKanbanCounters() {
                    var actCards = document.querySelectorAll('#projectsKanbanContainer .kanban-column[data-column-status="active"] .project-kanban-card');
                    var progCards = document.querySelectorAll('#projectsKanbanContainer .kanban-column[data-column-status="in_progress"] .project-kanban-card');
                    var compCards = document.querySelectorAll('#projectsKanbanContainer .kanban-column[data-column-status="completed"] .project-kanban-card');

                    var actCount = 0, progCount = 0, compCount = 0;
                    actCards.forEach(function(c) { if (c.style.display !== 'none') actCount++; });
                    progCards.forEach(function(c) { if (c.style.display !== 'none') progCount++; });
                    compCards.forEach(function(c) { if (c.style.display !== 'none') compCount++; });

                    var bAct = document.getElementById('kanbanCountActive');
                    var bProg = document.getElementById('kanbanCountProgress');
                    var bComp = document.getElementById('kanbanCountCompleted');
                    if (bAct) bAct.innerText = actCount;
                    if (bProg) bProg.innerText = progCount;
                    if (bComp) bComp.innerText = compCount;
                }

                function filterProjectCards(query) {
                    var q = (query || '').toLowerCase().trim();
                    var cards = document.querySelectorAll('#projectCardsContainer .project-card-item');
                    cards.forEach(function(card) {
                        var cardName = (card.getAttribute('data-name') || '').toLowerCase();
                        var cardText = (card.innerText || '').toLowerCase();
                        if (!q || cardName.includes(q) || cardText.includes(q)) {
                            card.style.display = '';
                        } else {
                            card.style.display = 'none';
                        }
                    });
                    var kanbanCards = document.querySelectorAll('#projectsKanbanContainer .project-kanban-card');
                    kanbanCards.forEach(function(card) {
                        var cardName = (card.getAttribute('data-name') || '').toLowerCase();
                        var cardText = (card.innerText || '').toLowerCase();
                        if (!q || cardName.includes(q) || cardText.includes(q)) {
                            card.style.display = '';
                        } else {
                            card.style.display = 'none';
                        }
                    });
                    updateKanbanCounters();
                }

                function filterProjectStatus(status) {
                    var s = (status || 'all').toLowerCase().trim();
                    var cards = document.querySelectorAll('#projectCardsContainer .project-card-item');
                    cards.forEach(function(card) {
                        var cardStatus = (card.getAttribute('data-status') || '').toLowerCase();
                        if (s === 'all' || cardStatus === s) {
                            card.style.display = '';
                        } else {
                            card.style.display = 'none';
                        }
                    });
                    var kanbanCols = document.querySelectorAll('#projectsKanbanContainer .kanban-column');
                    kanbanCols.forEach(function(col) {
                        var colStatus = (col.getAttribute('data-column-status') || '').toLowerCase();
                        if (s === 'all') {
                            col.style.display = '';
                        } else if (s === 'active' && colStatus === 'active') {
                            col.style.display = '';
                        } else if (s === 'completed' && colStatus === 'completed') {
                            col.style.display = '';
                        } else {
                            col.style.display = 'none';
                        }
                    });
                    updateKanbanCounters();
                }

                function showAixoCreateModal() {
                    switchAixoTab('create_ticket');
                }

                function goToMyTickets() {
                    switchAixoTab('tickets');
                }

                function execEditorFormat(cmd, val) {
                    document.execCommand(cmd, false, val || null);
                    var ed = document.getElementById('ticketDescriptionEditor');
                    if (ed) ed.focus();
                }

                function insertEditorLink() {
                    var url = prompt('Enter link URL (e.g. https://example.com):', 'https://');
                    if (url && url !== 'https://') {
                        execEditorFormat('createLink', url);
                    }
                }

                function openProjectDropdown() {
                    var dd = document.getElementById('projectDropdownList');
                    if (dd) dd.style.display = 'block';
                }

                function toggleProjectDropdown() {
                    var dd = document.getElementById('projectDropdownList');
                    if (!dd) return;
                    dd.style.display = (dd.style.display === 'block') ? 'none' : 'block';
                }

                function filterProjectDropdown(val) {
                    var dd = document.getElementById('projectDropdownList');
                    if (dd) dd.style.display = 'block';
                    var q = (val || '').toLowerCase().trim();
                    var items = document.querySelectorAll('#projectDropdownList .m2o-item');
                    var exactMatch = false;
                    items.forEach(function(item) {
                        var name = (item.getAttribute('data-name') || '').toLowerCase();
                        if (!q || name.indexOf(q) > -1) {
                            item.style.display = 'flex';
                            if (name === q) exactMatch = true;
                        } else {
                            item.style.display = 'none';
                        }
                    });

                    var createOpt = document.getElementById('m2oCreateOption');
                    var createTxt = document.getElementById('m2oCreateText');
                    if (createOpt && createTxt) {
                        if (q && !exactMatch) {
                            createTxt.innerText = val.trim();
                            createOpt.style.display = 'block';
                        } else {
                            createOpt.style.display = 'none';
                        }
                    }
                }

                function selectExistingProject(elem) {
                    var id = elem.getAttribute('data-id');
                    var name = elem.getAttribute('data-name');
                    var inp = document.getElementById('projectMany2OneInput');
                    var idInp = document.getElementById('ticketProjectIdInput');
                    var newInp = document.getElementById('newProjectNameInput');
                    if (inp) inp.value = name;
                    if (idInp) idInp.value = id;
                    if (newInp) newInp.value = '';
                    var dd = document.getElementById('projectDropdownList');
                    if (dd) dd.style.display = 'none';

                    var sidebarPrjName = document.getElementById('relProjCardName');
                    var sidebarPrjBadge = document.getElementById('relProjCardBadge');
                    if (sidebarPrjName) sidebarPrjName.innerText = name;
                    if (sidebarPrjBadge) sidebarPrjBadge.innerText = (name || 'P').substring(0, 2).toUpperCase();
                }

                function selectNewProject() {
                    var inp = document.getElementById('projectMany2OneInput');
                    var val = inp ? inp.value.trim() : '';
                    if (!val) return;
                    var idInp = document.getElementById('ticketProjectIdInput');
                    var newInp = document.getElementById('newProjectNameInput');
                    if (idInp) idInp.value = '';
                    if (newInp) newInp.value = val;
                    var dd = document.getElementById('projectDropdownList');
                    if (dd) dd.style.display = 'none';

                    var sidebarPrjName = document.getElementById('relProjCardName');
                    var sidebarPrjBadge = document.getElementById('relProjCardBadge');
                    if (sidebarPrjName) sidebarPrjName.innerText = val;
                    if (sidebarPrjBadge) sidebarPrjBadge.innerText = (val || 'P').substring(0, 2).toUpperCase();
                }

                function validateAndSubmitCreateTicket(form) {
                    var editor = document.getElementById('ticketDescriptionEditor');
                    var hiddenDesc = document.getElementById('hiddenTicketDescription');
                    if (editor && hiddenDesc) {
                        var htmlContent = editor.innerHTML;
                        var textContent = editor.innerText.trim();
                        if (!textContent) {
                            alert('Please enter a description for your ticket.');
                            editor.focus();
                            return false;
                        }
                        hiddenDesc.value = htmlContent;
                    }
                    return true;
                }

                document.addEventListener('click', function(e) {
                    var wrapper = document.getElementById('projectMany2OneWrapper');
                    if (wrapper && !wrapper.contains(e.target)) {
                        var dd = document.getElementById('projectDropdownList');
                        if (dd) dd.style.display = 'none';
                    }
                });

                function openExistingTicketDropdown() {
                    var dd = document.getElementById('existingTicketDropdownList');
                    if (dd) dd.style.display = 'block';
                    var inp = document.getElementById('existingTicketMany2OneInput');
                    filterExistingTicketDropdown(inp ? inp.value : '');
                }

                function toggleExistingTicketDropdown() {
                    var dd = document.getElementById('existingTicketDropdownList');
                    if (!dd) return;
                    if (dd.style.display === 'block') {
                        dd.style.display = 'none';
                    } else {
                        openExistingTicketDropdown();
                    }
                }

                function filterExistingTicketDropdown(val) {
                    var dd = document.getElementById('existingTicketDropdownList');
                    if (dd) dd.style.display = 'block';
                    var q = (val || '').toLowerCase().trim();
                    var items = document.querySelectorAll('#existingTicketDropdownList .m2o-ticket-item');
                    var matchCount = 0;
                    items.forEach(function(item) {
                        var id = item.getAttribute('data-id');
                        var label = (item.getAttribute('data-label') || '').toLowerCase();
                        if (!id) {
                            item.style.display = !q ? 'flex' : 'none';
                            return;
                        }
                        if (!q || label.indexOf(q) > -1) {
                            item.style.display = 'flex';
                            matchCount++;
                        } else {
                            item.style.display = 'none';
                        }
                    });
                    var noMsg = document.getElementById('noExistingTicketsMsg');
                    if (noMsg) {
                        noMsg.style.display = (matchCount === 0 && q) ? 'block' : 'none';
                    }
                }

                window._lastSelectedExistingTicketElem = null;

                function showExistingTicketHoverPopup(el, ev) {
                    var pop = document.getElementById('ticketPreviewPopupCard');
                    if (!pop || !el) return;
                    if (pop.dataset.pinned === 'true') return;

                    var num = el.getAttribute('data-ref') || ('#' + (el.getAttribute('data-id') || ''));
                    var subj = el.getAttribute('data-subject') || '';
                    var st = el.getAttribute('data-stage') || 'Solved';
                    var proj = el.getAttribute('data-project') || 'General Support';
                    var cust = el.getAttribute('data-customer') || 'Customer';
                    var prio = el.getAttribute('data-priority') || 'Low';
                    var dt = el.getAttribute('data-close') || el.getAttribute('data-date') || '';
                    var desc = el.getAttribute('data-desc') || 'No additional resolution notes available.';

                    var popNum = document.getElementById('tktPopNumber');
                    var popSubj = document.getElementById('tktPopSubject');
                    var popStage = document.getElementById('tktPopStage');
                    var popProj = document.getElementById('tktPopProject');
                    var popCust = document.getElementById('tktPopCustomer');
                    var popPrio = document.getElementById('tktPopPriority');
                    var popDt = document.getElementById('tktPopDate');
                    var popDesc = document.getElementById('tktPopDesc');

                    if (popNum) popNum.textContent = num;
                    if (popSubj) popSubj.textContent = subj;
                    if (popStage) popStage.textContent = st;
                    if (popProj) popProj.textContent = proj;
                    if (popCust) popCust.textContent = cust;
                    if (popPrio) {
                        var prioLower = prio.toLowerCase();
                        var pColor = prioLower === 'urgent' ? '#DC2626' : (prioLower === 'medium' ? '#B45309' : '#1D4ED8');
                        popPrio.innerHTML = '● ' + prio + '';
                    }
                    if (popDt) popDt.textContent = dt;
                    if (popDesc) {
                        var tmp = document.createElement('div');
                        tmp.innerHTML = desc;
                        var cleanTxt = tmp.textContent || tmp.innerText || desc;
                        popDesc.textContent = cleanTxt.length > 180 ? cleanTxt.substring(0, 180) + '...' : cleanTxt;
                    }

                    var rect = el.getBoundingClientRect();
                    var top = rect.top;
                    var left = rect.right + 14;
                    if (left + 350 > window.innerWidth) {
                        left = rect.left - 355;
                    }
                    if (left < 10) left = 10;
                    if (top + 280 > window.innerHeight) {
                        top = window.innerHeight - 290;
                    }
                    if (top < 10) top = 10;

                    pop.style.top = top + 'px';
                    pop.style.left = left + 'px';
                    pop.style.display = 'block';
                    pop.style.opacity = '1';
                }

                function hideExistingTicketHoverPopup() {
                    var pop = document.getElementById('ticketPreviewPopupCard');
                    if (pop && pop.dataset.pinned !== 'true') {
                        pop.style.display = 'none';
                    }
                }

                function selectExistingTicketM2O(elem) {
                    var id = elem.getAttribute('data-id') || '';
                    var label = elem.getAttribute('data-label') || '';
                    var ref = elem.getAttribute('data-ref') || ('#' + id);
                    var subj = elem.getAttribute('data-subject') || '';
                    var proj = elem.getAttribute('data-project') || '';
                    var stage = elem.getAttribute('data-stage') || 'Solved';

                    var inp = document.getElementById('existingTicketMany2OneInput');
                    var idInp = document.getElementById('existingTicketIdInput');
                    if (inp) inp.value = label;
                    if (idInp) idInp.value = id;

                    window._lastSelectedExistingTicketElem = elem;

                    var selCard = document.getElementById('existingTicketSelectedCard');
                    var badge = document.getElementById('selectedTktBadge');
                    var title = document.getElementById('selectedTktTitle');
                    var meta = document.getElementById('selectedTktMeta');
                    if (selCard) {
                        selCard.style.display = 'flex';
                        if (badge) badge.textContent = ref;
                        if (title) title.textContent = subj;
                        if (meta) meta.textContent = (proj ? proj + ' • ' : '') + stage;
                    }

                    var dd = document.getElementById('existingTicketDropdownList');
                    if (dd) dd.style.display = 'none';
                    hideExistingTicketHoverPopup();
                }

                function clearExistingTicketSelectionM2O(e) {
                    if (e && e.stopPropagation) e.stopPropagation();
                    var inp = document.getElementById('existingTicketMany2OneInput');
                    var idInp = document.getElementById('existingTicketIdInput');
                    var selCard = document.getElementById('existingTicketSelectedCard');
                    if (inp) inp.value = '';
                    if (idInp) idInp.value = '';
                    if (selCard) selCard.style.display = 'none';
                    window._lastSelectedExistingTicketElem = null;
                    var pop = document.getElementById('ticketPreviewPopupCard');
                    if (pop) {
                        pop.dataset.pinned = '';
                        pop.style.display = 'none';
                    }
                }

                function popupShowSelectedDetails(e) {
                    if (e && e.stopPropagation) e.stopPropagation();
                    if (!window._lastSelectedExistingTicketElem) return;
                    showExistingTicketHoverPopup(window._lastSelectedExistingTicketElem, e);
                    var pop = document.getElementById('ticketPreviewPopupCard');
                    if (pop) {
                        pop.dataset.pinned = 'true';
                        pop.style.pointerEvents = 'auto';
                        var rect = (e.currentTarget || e.target).getBoundingClientRect();
                        var top = rect.bottom + 8;
                        var left = rect.left - 160;
                        if (left + 350 > window.innerWidth) left = window.innerWidth - 360;
                        if (left < 10) left = 10;
                        if (top + 280 > window.innerHeight) top = rect.top - 290;
                        pop.style.top = top + 'px';
                        pop.style.left = left + 'px';
                        pop.style.display = 'block';

                        function closePinned(ev) {
                            if (!pop.contains(ev.target)) {
                                pop.dataset.pinned = '';
                                pop.style.pointerEvents = 'none';
                                pop.style.display = 'none';
                                document.removeEventListener('click', closePinned);
                            }
                        }
                        setTimeout(function() {
                            document.addEventListener('click', closePinned);
                        }, 120);
                    }
                }

                document.addEventListener('click', function(e) {
                    var wrapper = document.getElementById('existingTicketMany2OneWrapper');
                    if (wrapper && !wrapper.contains(e.target)) {
                        var dd = document.getElementById('existingTicketDropdownList');
                        if (dd) dd.style.display = 'none';
                    }
                });

                document.addEventListener('DOMContentLoaded', function() {
                    var etInput = document.getElementById('existingTicketMany2OneInput');
                    if (etInput) {
                        etInput.addEventListener('input', function() {
                            if (!this.value.trim()) {
                                var idInp = document.getElementById('existingTicketIdInput');
                                if (idInp) idInp.value = '';
                            }
                        });
                    }
                });


                function switchCustomerTicketStage(stageKey) {
                    var stages = ['conversation', 'details', 'attachments', 'project', 'activity'];
                    stages.forEach(function(s) {
                        var pane = document.getElementById('custStage_' + s);
                        var btn = document.getElementById('custTabBtn_' + s);
                        if (pane) {
                            pane.style.display = (s === stageKey) ? 'block' : 'none';
                        }
                        if (btn) {
                            if (s === stageKey) {
                                btn.style.border = '1.5px solid #2563eb';
                                btn.style.color = '#2563eb';
                                btn.style.background = '#eff6ff';
                                btn.style.fontWeight = '700';
                            } else {
                                btn.style.border = '1.5px solid transparent';
                                btn.style.color = '#475569';
                                btn.style.background = 'transparent';
                                btn.style.fontWeight = '500';
                            }
                        }
                    });
                }

                function handleCustAttachUpload(input) {
                    if (input.files && input.files[0]) {
                        var f = input.files[0];
                        var ticket = window.currentActiveTicket;
                        var ticketId = ticket ? ticket.id : null;
                        if (!ticketId) {
                            alert('Please select an active ticket first to upload an attachment.');
                            input.value = '';
                            return;
                        }
                        var formData = new FormData();
                        formData.append('ticket_id', ticketId);
                        formData.append('attachment', f);

                        fetch('/helpdesk/ticket/attachment/upload', {
                            method: 'POST',
                            body: formData
                        }).then(function(r) { return r.json(); }).then(function(data) {
                            input.value = '';
                            if (data.success && data.attachment) {
                                var a = data.attachment;
                                var list = document.getElementById('custAttachmentsList');
                                if (list) {
                                    var emptyNotice = list.querySelector('.col-12');
                                    if (emptyNotice) emptyNotice.remove();

                                    var col = document.createElement('div');
                                    col.className = 'col-md-4';
                                    var sz = a.file_size ? (Math.round(a.file_size / 1024) + ' KB') : '';
                                    col.innerHTML = '
' +
                                        '

' +
                                        '
' +
                                        '' +
                                        '

' + a.name + '' +
                                        '
' + sz + (sz ? ' • ' : '') + (a.create_date || 'Just now') + '' +
                                        '
Uploaded by ' + (a.author || 'You') + '' +
                                        '
' +
                                        'Uploaded' +
                                        '' +
                                        ' Download' +
                                        '';
                                    list.insertBefore(col, list.firstChild);

                                    var badge = document.getElementById('custAttachCountBadge');
                                    if (badge) {
                                        var count = parseInt(badge.innerText || '0', 10) + 1;
                                        badge.innerText = count;
                                    }
                                }
                                alert('File "' + a.name + '" attached successfully!');
                            } else {
                                alert('Failed to upload file: ' + ((data && data.error) || 'Server error'));
                            }
                        }).catch(function(err) {
                            input.value = '';
                            console.error('Upload error:', err);
                            alert('Network error while uploading file.');
                        });
                    }
                }

                                function fallbackLoadCustomerMessages(ticketId) {
                    var chatBox = document.getElementById('aixoChatBox');
                    fetch('/helpdesk/chat/messages/' + ticketId, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { role: 'customer' } })
                    }).then(function(r) { return r.json(); }).then(function(resp) {
                        var res = resp ? resp.result : null;
                        if (res && res.messages && res.messages.length > 0) {
                            if (typeof window.renderCustomerChatMessages === 'function') {
                                window.renderCustomerChatMessages(res.messages, []);
                            }
                        } else if (chatBox) {
                            chatBox.innerHTML = '';
                        }
                    }).catch(function() {
                        if (chatBox) {
                            chatBox.innerHTML = '';
                        }
                    });
                }

                function openAixoDetail(id, code, subject, proj, prio, desc, stage, category, tags) {
                    // Check if called with legacy signature (5 args: code, subject, proj, prio, desc)
                    if (arguments.length <= 5 && isNaN(id) && typeof id === 'string' && id.startsWith('#')) {
                        code = arguments[0];
                        subject = arguments[1];
                        proj = arguments[2];
                        prio = arguments[3];
                        desc = arguments[4];
                        id = '';
                        stage = 'new';
                        category = 'billing';
                        tags = '';
                    }

                    window.currentActiveTicket = {
                        id: id || '',
                        code: code || '',
                        subject: subject || '',
                        proj: proj || '-',
                        prio: prio || 'Normal',
                        desc: desc || '',
                        stage: stage || 'new',
                        category: category || 'billing',
                        tags: tags || ''
                    };

                    if (id) {
                        try {
                            localStorage.setItem('helpdesk_cust_active_tab', 'ticket_detail');
                            localStorage.setItem('helpdesk_cust_active_ticket_id', String(id));
                            if (window.history && window.history.replaceState) {
                                window.history.replaceState(null, '', '#ticket_' + id);
                            } else {
                                window.location.hash = '#ticket_' + id;
                            }
                        } catch(e) {}
                    }

                    document.querySelectorAll('.aixo-screen-view').forEach(function(s) { s.classList.remove('active'); });
                    var detScreen = document.getElementById('scrDetail');
                    if (detScreen) detScreen.classList.add('active');

                    // Header elements
                    var dCode = document.getElementById('aixoDetCode');
                    if (dCode) dCode.innerText = code || ('#' + id);
                    var dSub = document.getElementById('aixoDetSubject');
                    if (dSub) dSub.innerText = subject;
                    var dProj = document.getElementById('aixoDetProj');
                    if (dProj) dProj.innerText = proj || '-';
                    var dPrio = document.getElementById('aixoDetPriority');
                    if (dPrio) {
                        dPrio.innerText = prio || 'Normal';
                        if (prio === 'Critical' || prio === '2') {
                            dPrio.style.background = '#fee2e2';
                            dPrio.style.color = '#dc2626';
                        } else if (prio === 'High' || prio === '1') {
                            dPrio.style.background = '#fee2e2';
                            dPrio.style.color = '#dc2626';
                        } else if (prio === 'Medium') {
                            dPrio.style.background = '#fef3c7';
                            dPrio.style.color = '#d97706';
                        } else {
                            dPrio.style.background = '#dcfce7';
                            dPrio.style.color = '#059669';
                        }
                    }
                    var dStage = document.getElementById('aixoDetStage');
                    if (dStage) {
                        var isOp = (stage === 'new' || stage === 'open');
                        var isProg = (stage === 'progress');
                        var isPend = (stage === 'on_hold' || stage === 'rotting');
                        var isRes = (stage === 'solved' || stage === 'resolved');
                        var stgLabel = isOp ? 'Open' : (isProg ? 'In Progress' : (isPend ? 'Pending' : (isRes ? 'Resolved' : 'Closed')));
                        dStage.innerText = stgLabel;
                        if (isOp) {
                            dStage.style.background = '#dbeafe';
                            dStage.style.color = '#2563eb';
                        } else if (isProg) {
                            dStage.style.background = '#ede9fe';
                            dStage.style.color = '#7c3aed';
                        } else if (isPend) {
                            dStage.style.background = '#fef3c7';
                            dStage.style.color = '#f59e0b';
                        } else if (isRes) {
                            dStage.style.background = '#dcfce7';
                            dStage.style.color = '#10b981';
                        } else {
                            dStage.style.background = '#fee2e2';
                            dStage.style.color = '#ef4444';
                        }
                    }
                    var dDesc = document.getElementById('aixoDetDesc');
                    if (dDesc) {
                        var tempDiv = document.createElement('div');
                        tempDiv.innerHTML = desc || '';
                        var rawText = tempDiv.textContent || tempDiv.innerText || desc || '';
                        var lines = rawText.split(/\r?\n/).map(function(l) { return l.trim(); }).filter(Boolean);
                        var uniqueLines = [];
                        lines.forEach(function(l) {
                            if (!uniqueLines.includes(l)) {
                                uniqueLines.push(l);
                            }
                        });
                        dDesc.innerText = uniqueLines.join(' ') || 'No description provided.';
                    }

                    // Detail tab elements
                    var dtSub = document.getElementById('custDetSubjectVal');
                    if (dtSub) dtSub.innerText = subject;
                    var dtCode = document.getElementById('custDetCodeVal');
                    if (dtCode) dtCode.innerText = code || ('#' + id);
                    var dtPrj = document.getElementById('custDetProjVal');
                    if (dtPrj) dtPrj.innerText = proj || '-';
                    var dtPrio = document.getElementById('custDetPrioVal');
                    if (dtPrio) dtPrio.innerText = prio || 'Normal';
                    var dtStage = document.getElementById('custDetStageVal');
                    if (dtStage) {
                        var stgVal = (stage === 'new' || stage === 'open') ? 'Open' : (stage === 'progress' ? 'In Progress' : ((stage === 'on_hold' || stage === 'rotting') ? 'Pending' : ((stage === 'solved' || stage === 'resolved') ? 'Resolved' : 'Closed')));
                        dtStage.innerText = stgVal;
                    }
                    var dtCat = document.getElementById('custDetCategoryVal');
                    if (dtCat) {
                        var catMap = { 'billing': 'Billing & Payments', 'technical': 'Technical & App Crash', 'refund': 'Refund & Returns', 'account': 'Account & Access', 'other': 'General Inquiry', 'feature': 'Feature Request' };
                        dtCat.innerText = catMap[category] || category || 'Billing & Payments';
                    }
                    var dtTags = document.getElementById('custDetTagsContainer');
                    if (dtTags) {
                        var tagArr = (tags || 'Support').split(',').map(function(t) { return t.trim(); }).filter(Boolean);
                        if (!tagArr.length) tagArr = ['Support'];
                        dtTags.innerHTML = tagArr.map(function(t) { return '' + t + ''; }).join(' ');
                    }

                    // Define reusable Customer Chat Renderer
                    window.renderCustomerChatMessages = function(messages, attachments) {
                        var chatBox = document.getElementById('aixoChatBox');
                        if (!chatBox) return;
                        var validMsgs = (messages || []).filter(function(m) {
                            var b = (m.body || '').toLowerCase();
                            var s = (m.sender_name || '').toLowerCase();
                            return s.indexOf('acme') === -1 && b.indexOf('we have received ticket') === -1;
                        });
                        if (validMsgs.length === 0) {
                            chatBox.innerHTML = '';
                            return;
                        }

                        var wasAtBottom = (chatBox.scrollHeight - chatBox.scrollTop - chatBox.clientHeight < 90);
                        chatBox.innerHTML = '';

                        // Centered Date Divider
                        var dateDivider = document.createElement('div');
                        dateDivider.style = 'display: flex; align-items: center; justify-content: center; margin: 10px 0; width: 100%;';
                        dateDivider.innerHTML = '<div style="flex: 1; height: 1px; background: #E2E8F0;"></div><span style="padding: 0 14px; font-size: 11px; font-weight: 600; color: #64748B; text-transform: uppercase; letter-spacing: 0.04em;">Today</span><div style="flex: 1; height: 1px; background: #E2E8F0;"></div>';
                        chatBox.appendChild(dateDivider);

                        validMsgs.forEach(function(m) {
                            var mDiv = document.createElement('div');
                            mDiv.className = 'aixo-chat-msg-row';
                            var rawBody = m.body || '';

                            // Parse attached images
                            var attachedImages = [];
                            var imgRegex = /\[Attached image:\s*([^\]]+)\]/gi;
                            var match;
                            while ((match = imgRegex.exec(rawBody)) !== null) {
                                attachedImages.push(match[1].trim());
                            }
                            rawBody = rawBody.replace(/\[Attached image:\s*([^\]]+)\]/gi, '').trim();

                            // Parse attached files
                            var attachedFiles = [];
                            var fileRegex = /\[Attached file:\s*([^\]]+)\]/gi;
                            while ((match = fileRegex.exec(rawBody)) !== null) {
                                attachedFiles.push(match[1].trim());
                            }
                            rawBody = rawBody.replace(/\[Attached file:\s*([^\]]+)\]/gi, '').trim();

                            // Build media cards
                            var mediaHtml = '';
                            if (attachedImages.length > 0) {
                                mediaHtml += attachedImages.map(function(imgName) {
                                    var foundAtt = (attachments || []).find(function(a) {
                                        return a.name && (a.name.trim().toLowerCase() === imgName.toLowerCase() || a.name.toLowerCase().indexOf(imgName.toLowerCase()) !== -1 || imgName.toLowerCase().indexOf(a.name.toLowerCase()) !== -1);
                                    });
                                    var imgViewUrl = foundAtt ? (foundAtt.view_url || ('/helpdesk/attachment/view/' + foundAtt.id)) : ('/helpdesk/ticket/attachment/download?name=' + encodeURIComponent(imgName));
                                    return '<div style="margin-top: 6px; display: flex; align-items: center; gap: 8px; padding: 8px 12px; background: #F0F7FF; border: 1px solid #DBEAFE; border-radius: 8px; cursor: pointer; transition: all 0.15s;" onclick="openSameScreenImageModal(\'' + imgViewUrl + '\', \'' + imgName.replace(/'/g, "\\'") + '\')">' +
                                        '<svg viewBox="0 0 24 24" width="17" height="17" stroke="#2563EB" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 15-5-5L5 21"/></svg>' +
                                        '<span style="font-size: 12.5px; font-weight: 600; color: #2563EB; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 240px;">' + imgName + '</span>' +
                                    '</div>';
                                }).join('');
                            }

                            if (attachedFiles.length > 0) {
                                mediaHtml += attachedFiles.map(function(fileName) {
                                    var foundAtt = (attachments || []).find(function(a) {
                                        return a.name && (a.name.trim().toLowerCase() === fileName.toLowerCase() || a.name.toLowerCase().indexOf(fileName.toLowerCase()) !== -1 || fileName.toLowerCase().indexOf(a.name.toLowerCase()) !== -1);
                                    });
                                    var fileDlUrl = foundAtt ? (foundAtt.url || ('/helpdesk/attachment/download/' + foundAtt.id)) : ('/helpdesk/ticket/attachment/download?name=' + encodeURIComponent(fileName));
                                    var fileSize = foundAtt ? ((foundAtt.file_size > 1024) ? Math.round(foundAtt.file_size / 1024) + ' KB' : (foundAtt.file_size || 0) + ' B') : '';
                                    return '<div style="margin-top: 6px; display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 12px; background: #F0F7FF; border: 1px solid #DBEAFE; border-radius: 8px;">' +
                                        '<div style="display: flex; align-items: center; gap: 8px; overflow: hidden; min-width: 0;">' +
                                            '<svg viewBox="0 0 24 24" width="17" height="17" stroke="#2563EB" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/><path d="M8 13h8M8 17h8"/></svg>' +
                                            '<div style="overflow: hidden; min-width: 0;">' +
                                                '<div style="font-size: 12.5px; font-weight: 600; color: #2563EB; text-overflow: ellipsis; overflow: hidden; white-space: nowrap;">' + fileName + '</div>' +
                                                (fileSize ? ('<div style="font-size: 10.5px; color: #64748B;">' + fileSize + '</div>') : '') +
                                            '</div>' +
                                        '</div>' +
                                        '<button type="button" onclick="downloadAttachmentDirect(\'' + fileDlUrl + '\', \'' + fileName.replace(/'/g, "\\'") + '\')" style="background: transparent; border: none; color: #2563EB; cursor: pointer; padding: 4px; display: inline-flex; align-items: center;" title="Download file"><svg viewBox="0 0 24 24" width="16" height="16" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg></button>' +
                                    '</div>';
                                }).join('');
                            }

                            if (m.author_type === 'customer') {
                                // Customer (current user): WhatsApp Style Outgoing Bubble on the RIGHT side
                                var isRead = !!m.is_read;
                                var tickColor = isRead ? '#53BDEB' : '#94A3B8';
                                mDiv.style = 'display: flex; flex-direction: column; align-items: flex-end; width: 100%; margin-bottom: 8px;';
                                mDiv.innerHTML = '<div style="max-width: 78%; background: #D9FDD3; border: 1px solid #C1F3BA; border-radius: 14px 14px 2px 14px; padding: 8px 12px 6px 12px; box-shadow: 0 1px 2px rgba(0,0,0,0.05); word-break: break-word; position: relative;">' +
                                    '<div style="display: flex; align-items: center; justify-content: flex-start; gap: 6px; margin-bottom: 3px;">' +
                                        '<span style="font-size: 12px; font-weight: 700; color: #059669;">(You)</span>' +
                                    '</div>' +
                                    (rawBody ? ('<div style="font-size: 13.5px; color: #0F172A; line-height: 1.45; white-space: pre-wrap;">' + rawBody + '</div>') : '') +
                                    mediaHtml +
                                    '<div style="display: flex; align-items: center; justify-content: flex-end; gap: 4px; margin-top: 4px;">' +
                                        '<span style="font-size: 10.5px; color: #64748B;">' + (m.time || 'Recently') + '</span>' +
                                        '<span style="color: ' + tickColor + '; display: inline-flex;" title="' + (isRead ? 'Read' : 'Delivered') + '"><svg width="15" height="11" viewBox="0 0 16 11" fill="none"><path d="M11.05 1L4.85 7.2L2.05 4.4L1 5.45L4.85 9.3L12.1 2.05L11.05 1Z" fill="' + tickColor + '"/><path d="M15.05 1L8.85 7.2L7.65 6L6.6 7.05L8.85 9.3L16.1 2.05L15.05 1Z" fill="' + tickColor + '"/></svg></span>' +
                                    '</div>' +
                                '</div>';
                            } else {
                                // Opposite person (Administrator / Employee): placed on the LEFT side
                                var empSender = (m.sender_name || 'Support Specialist');
                                if (empSender.toLowerCase().indexOf('acme') !== -1 || empSender.toLowerCase() === 'admin' || empSender.toLowerCase() === 'user') {
                                    empSender = 'Administrator';
                                }
                                var empInit = empSender.substring(0, 2).toUpperCase();
                                mDiv.style = 'display: flex; align-items: flex-start; gap: 10px; width: 100%; margin-bottom: 14px;';
                                mDiv.innerHTML = '<div style="display: flex; flex-direction: column; align-items: center; gap: 3px; flex-shrink: 0;">' +
                                    '<div style="width: 36px; height: 36px; border-radius: 50%; background: #ECFDF5; color: #059669; font-weight: 700; font-size: 13px; display: flex; align-items: center; justify-content: center; border: 1px solid #A7F3D0; box-shadow: 0 1px 2px rgba(0,0,0,0.06);">' + empInit + '</div>' +
                                    '<span style="font-size: 10px; color: #94A3B8; font-weight: 500;">' + (m.time || 'Recently') + '</span>' +
                                '</div>' +
                                '<div style="max-width: 78%; background: #FFFFFF; border: 1px solid #E2E8F0; border-radius: 4px 16px 16px 16px; padding: 12px 14px; box-shadow: 0 2px 8px rgba(0,0,0,0.04); word-break: break-word;">' +
                                    '<div style="display: flex; align-items: center; justify-content: flex-start; gap: 8px; margin-bottom: 4px;">' +
                                        '<span style="font-size: 12.5px; font-weight: 700; color: #059669;">' + empSender + '</span>' +
                                    '</div>' +
                                    mediaHtml +
                                    (rawBody ? ('<div style="font-size: 13.5px; color: #0F172A; line-height: 1.45; white-space: pre-wrap; margin-top: ' + (mediaHtml ? '8px' : '2px') + ';">' + rawBody + '</div>') : '') +
                                '</div>';
                            }
                            chatBox.appendChild(mDiv);
                        });

                        if (wasAtBottom) {
                            chatBox.scrollTop = chatBox.scrollHeight;
                        }
                    };

                            chatBox.innerHTML = '';
                    var chatBox = document.getElementById('aixoChatBox');
                    if (chatBox) {
                        chatBox.innerHTML = '<div class="text-center py-4 text-muted"><div class="spinner-border spinner-border-sm text-primary me-2"></div>Loading conversation...</div>';
                    }

                    // Fetch live details from server
                    if (id) {
                        fetch('/helpdesk/ticket/get_detail/' + id, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { role: 'customer' } })
                        }).then(function(r) { return r.json(); }).then(function(resp) {
                            var res = resp ? resp.result : null;
                            if (res && (res.success || res.messages || res.ticket)) {
                                // 1. Chat Messages
                                window.renderCustomerChatMessages(res.messages, res.attachments);
                                window._lastCustomerMsgSignature = JSON.stringify((res.messages || []).map(function(m) { return (m.id || '') + ':' + (m.body || '') + ':' + (m.time || '') + ':' + (m.is_read ? '1' : '0'); }));

                                // 2. Attachments List and Tab Badge
                                var attList = document.getElementById('custAttachmentsList');
                                var attBadge = document.getElementById('custAttachCountBadge');
                                if (attBadge) attBadge.innerText = (res.attachments ? res.attachments.length : 0);
                                if (attList) {
                                    attList.innerHTML = '';
                                    if (res.attachments && res.attachments.length > 0) {
                                        res.attachments.forEach(function(a) {
                                            var col = document.createElement('div');
                                            col.className = 'col-md-4';
                                            var sz = a.file_size ? (Math.round(a.file_size / 1024) + ' KB') : '';
                                            var dlUrl = a.url || ('/helpdesk/attachment/download/' + a.id);
                                            var viewUrl = a.view_url || ('/helpdesk/attachment/view/' + a.id);
                                            var isImg = (a.name && /\.(png|jpe?g|gif|webp|svg)$/i.test(a.name)) || (a.mimetype && a.mimetype.indexOf('image/') !== -1);
                                            col.innerHTML = '<div class="p-3 border rounded-3 h-100" style="background: #ffffff; display: flex; flex-direction: column; justify-content: space-between;">' +
                                                '<div><div class="d-flex align-items-center gap-3 mb-2" style="cursor: ' + (isImg ? 'pointer' : 'default') + ';" ' + (isImg ? ('onclick="openSameScreenImageModal(\'' + viewUrl + '\', \'' + a.name.replace(/'/g, "\\'") + '\')"') : '') + '>' +
                                                '<div style="width: 38px; height: 38px; border-radius: 8px; background: #eff6ff; color: #2563eb; display: flex; align-items: center; justify-content: center; flex-shrink: 0; overflow: hidden;">' +
                                                (isImg ? ('<img src="' + viewUrl + '" style="width: 100%; height: 100%; object-fit: cover;" onerror="this.onerror=null; this.outerHTML=\'<span style=\\\'font-size: 18px;\\\'>🖼️</span>\';"/>') : '<svg viewBox="0 0 24 24" width="20" height="20" stroke="currentColor" stroke-width="2" fill="none"><path d="M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5L14.5 2z"/><polyline points="14 2 14 8 20 8"/></svg>') + '</div>' +
                                                '<div style="min-width: 0; flex: 1;"><div class="fw-bold text-dark text-truncate" style="font-size: 13.5px;">' + a.name + (isImg ? ' <span style="font-size: 11px; font-weight: normal; color: #2563EB;">(View)</span>' : '') + '</div>' +
                                                '<div class="text-muted" style="font-size: 11.5px;">' + sz + (sz ? ' • ' : '') + (a.create_date || '') + '</div></div></div>' +
                                                '<div class="text-muted" style="font-size: 11.5px; margin-top: 6px;">Uploaded by ' + (a.author || 'User') + '</div></div>' +
                                                '<div class="d-flex justify-content-between align-items-center pt-3 mt-3 border-top">' +
                                                '<button type="button" onclick="downloadAttachmentDirect(\'' + dlUrl + '\', \'' + a.name.replace(/'/g, "\\'") + '\')" class="btn btn-sm btn-outline-primary d-inline-flex align-items-center gap-1" style="font-size: 12px; font-weight: 600;">' +
                                                '<svg viewBox="0 0 24 24" width="13" height="13" stroke="currentColor" stroke-width="2" fill="none"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg> Download</button>' +
                                                '</div></div>';
                                            attList.appendChild(col);
                                        });
                                    } else {
                                        attList.innerHTML = '<div class="col-12 text-center py-5 text-muted"><p class="small mb-0">No attachments uploaded for this ticket yet.</p></div>';
                                    }
                                }

                                // 3. Related Project and Siblings
                                var pTitle = document.getElementById('custProjTitle');
                                var pSub = document.getElementById('custProjSubtitle');
                                var pInit = document.getElementById('custProjInitials');
                                var pMgr = document.getElementById('custProjManager');
                                var pOwn = document.getElementById('custProjPartner');
                                if (res.project) {
                                    if (pTitle) pTitle.innerText = res.project.name;
                                    if (pSub) pSub.innerText = 'Project Code: #PRJ-' + res.project.id + ' • Live Project';
                                    if (pInit) pInit.innerText = res.project.initials;
                                    if (pMgr) pMgr.innerText = res.project.manager || 'Not Assigned';
                                    if (pOwn) pOwn.innerText = res.project.owner || '-';
