                function openTicketEditModal() {
                    var ticket = window.currentActiveTicket;
                    if (!ticket || !ticket.id) {
                        alert('Please open a ticket first to edit its record.');
                        return;
                    }
                    document.getElementById('editTicketId').value = ticket.id;
                    document.getElementById('editTicketSubject').value = ticket.subject || '';
                    var tempDiv = document.createElement('div');
                    tempDiv.innerHTML = ticket.desc || '';
                    document.getElementById('editTicketDesc').value = tempDiv.textContent || tempDiv.innerText || ticket.desc || '';

                    // Priority
                    var prioVal = (ticket.prio === 'Critical' || ticket.prio === '2') ? '2' : ((ticket.prio === 'High' || ticket.prio === '1') ? '1' : '0');
                    var pSel = document.getElementById('editTicketPriority');
                    if (pSel) pSel.value = prioVal;

                    // Stage
                    var stgVal = ticket.stage || 'new';
                    if (stgVal === 'open') stgVal = 'new';
                    if (stgVal === 'rotting') stgVal = 'on_hold';
                    if (stgVal === 'resolved') stgVal = 'solved';
                    var sSel = document.getElementById('editTicketStage');
                    if (sSel) sSel.value = stgVal;

                    // Project / Team
                    var tSel = document.getElementById('editTicketTeam');
                    if (tSel && ticket.proj) tSel.value = ticket.proj;

                    // Category
                    var cSel = document.getElementById('editTicketCategory');
                    if (cSel && ticket.category) cSel.value = ticket.category;

                    // Tags
                    var tagInp = document.getElementById('editTicketTags');
                    if (tagInp) tagInp.value = ticket.tags || '';

                    // Subtitle
                    var subElem = document.getElementById('editTicketModalSubtitle');
                    if (subElem) subElem.innerText = 'Editing ticket ' + (ticket.code || ('#' + ticket.id));

                    var alertBox = document.getElementById('editTicketAlert');
                    if (alertBox) alertBox.style.display = 'none';

                    var modal = document.getElementById('editTicketModal');
                    if (modal) modal.style.display = 'flex';
                }

                function closeTicketEditModal() {
                    var modal = document.getElementById('editTicketModal');
                    if (modal) modal.style.display = 'none';
                }

                function saveTicketEdits() {
                    var ticketId = document.getElementById('editTicketId').value;
                    var name = document.getElementById('editTicketSubject').value.trim();
                    var desc = document.getElementById('editTicketDesc').value.trim();
                    var priority = document.getElementById('editTicketPriority').value;
                    var stage = document.getElementById('editTicketStage').value;
                    var team = document.getElementById('editTicketTeam').value;
                    var category = document.getElementById('editTicketCategory').value;
                    var tags = document.getElementById('editTicketTags').value.trim();
                    var btn = document.getElementById('btnSaveTicketEdits');
                    var alertBox = document.getElementById('editTicketAlert');

                    if (!name) {
                        if (alertBox) {
                            alertBox.className = 'alert alert-danger py-2 px-3 mb-3';
                            alertBox.innerText = 'Subject is required.';
                            alertBox.style.display = 'block';
                        }
                        return;
                    }

                    if (btn) {
                        btn.disabled = true;
                        btn.innerText = 'Saving...';
                    }

                    fetch('/helpdesk/ticket/update', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0',
                            params: {
                                ticket_id: ticketId,
                                name: name,
                                description: desc,
                                priority: priority,
                                stage: stage,
                                team_name: team,
                                category: category,
                                tag_names: tags
                            }
                        })
                    })
                    .then(function(res) { return res.json(); })
                    .then(function(resp) {
                        if (btn) {
                            btn.disabled = false;
                            btn.innerText = 'Save Changes';
                        }
                        var result = resp.result || resp;
                        if (result && result.success) {
                            var d = result.data || {};
                            var prioText = priority === '2' ? 'Critical' : (priority === '1' ? 'High' : 'Normal');

                            // Refresh active ticket view in place
                            openAixoDetail(ticketId, d.ticket_number || ('#' + ticketId), name, team, prioText, desc, stage, category, tags);

                            // Update corresponding table row if present in list
                            var row = document.getElementById('ticketRow_' + ticketId);
                            if (row) {
                                var cells = row.querySelectorAll('td');
                                if (cells.length >= 6) {
                                    cells[2].innerText = name;
                                    cells[3].innerText = team;
                                    var prioBg = priority === '2' ? '#fef2f2; color: #ef4444;' : (priority === '1' ? '#fff7ed; color: #ea580c;' : '#f0fdf4; color: #16a34a;');
                                    cells[4].innerHTML = '' + prioText + '';
                                    var stgText = (stage === 'new' || stage === 'open') ? 'Open' : (stage === 'progress' ? 'In Progress' : ((stage === 'on_hold' || stage === 'rotting') ? 'Pending' : ((stage === 'solved' || stage === 'resolved') ? 'Resolved' : 'Closed')));
                                    var stgBadge = (stage === 'new' || stage === 'open') ? 'badge bg-danger-subtle text-danger border border-danger-subtle px-2 py-1 rounded-pill' : ('badge-aixo pill-st-' + (stage === 'solved' ? 'resolved' : (stage === 'cancelled' ? 'closed' : stage)));
                                    cells[5].innerHTML = '' + stgText + '';
                                }
                            }

                            if (alertBox) {
                                alertBox.className = 'alert alert-success py-2 px-3 mb-3';
                                alertBox.innerText = result.message || 'Ticket record updated successfully!';
                                alertBox.style.display = 'block';
                            }

                            setTimeout(function() {
                                closeTicketEditModal();
                            }, 900);
                        } else {
                            if (alertBox) {
                                alertBox.className = 'alert alert-danger py-2 px-3 mb-3';
                                alertBox.innerText = (result && result.message) ? result.message : 'Error updating ticket record.';
                                alertBox.style.display = 'block';
                            }
                        }
                    })
                    .catch(function(err) {
                        if (btn) {
                            btn.disabled = false;
                            btn.innerText = 'Save Changes';
                        }
                        if (alertBox) {
                            alertBox.className = 'alert alert-danger py-2 px-3 mb-3';
                            alertBox.innerText = 'Network error while updating ticket.';
                            alertBox.style.display = 'block';
                        }
                    });
                }

                function sendAixoReply() {
                    var inp = document.getElementById('aixoReplyInput');
                    var text = (inp.value || '').trim();
                    var selectedFile = window.selectedAixoReplyFile;
                    if (!text && !selectedFile) return;
                    var ticket = window.currentActiveTicket;
                    var ticketId = ticket ? ticket.id : null;
                    if (!ticketId) {
                        alert('Please select an active ticket first to send a reply.');
                        return;
                    }
                    var box = document.getElementById('aixoChatBox');
                    inp.disabled = true;
                    var uploadPromise = Promise.resolve(null);
                    if (selectedFile) {
                        var formData = new FormData();
                        formData.append('ticket_id', ticketId);
                        formData.append('attachment', selectedFile);
                        uploadPromise = fetch('/helpdesk/ticket/attachment/upload', {
                            method: 'POST',
                            body: formData
                        }).then(function(response) { return response.json(); }).then(function(result) {
                            if (!result.success) throw new Error(result.error || 'File upload failed.');
                            return result.attachment;
                        });
                    }

                    uploadPromise.then(function(attachment) {
                        var messageBody = text;
                        if (attachment) {
                            var fileName = selectedFile.name.replace(/\]/g, ')').replace(/[\r\n]/g, ' ');
                            var marker = selectedFile.type && selectedFile.type.indexOf('image/') === 0 ? '[Attached image: ' : '[Attached file: ';
                            messageBody = [messageBody, marker + fileName + ']'].filter(Boolean).join('\n');
                        }
                        return fetch('/helpdesk/chat/send', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                jsonrpc: '2.0',
                                method: 'call',
                                params: {
                                    ticket_id: ticketId,
                                    body: messageBody,
                                    author_type: 'customer'
                                }
                            })
                        });
                    }).then(function(response) { return response.json(); }).then(function(resp) {
                        var res = resp.result;
                        if (!res || !res.success) throw new Error((res && res.error) || 'Please try again.');

                        inp.disabled = false;
                        inp.value = '';
                        if (selectedFile) clearAixoReplyAttachment();
                        fetch('/helpdesk/ticket/get_detail/' + ticketId, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { role: 'customer' } })
                        }).then(function(response) { return response.json(); }).then(function(detailResponse) {
                            var detail = detailResponse.result;
                            if (detail && detail.success && typeof window.renderCustomerChatMessages === 'function') {
                                window.renderCustomerChatMessages(detail.messages, detail.attachments);
                                box.scrollTop = box.scrollHeight;
                            }
                        }).catch(function(err) {
                            console.error('Error refreshing customer conversation:', err);
                        });
                    }).catch(function(err) {
                        inp.disabled = false;
                        console.error('Error sending reply:', err);
                        alert(err.message || 'Network error while sending reply.');
                    });
                }

                function sendProjectDiscussionReply() {
                    var inp = document.getElementById('projectDiscussionInput');
                    var text = (inp.value || '').trim();
                    if (!text) return;
                    var ticket = window.currentActiveTicket;
                    var ticketId = ticket ? ticket.id : null;
                    if (!ticketId) {
                        alert('Please select or open a ticket first to communicate with your project team.');
                        return;
                    }
                    var box = document.getElementById('projectDiscussionsChatBox');
                    inp.disabled = true;

                    fetch('/helpdesk/chat/send', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0',
                            method: 'call',
                            params: {
                                ticket_id: ticketId,
                                body: text,
                                author_type: 'customer'
                            }
                        })
                    }).then(function(r) { return r.json(); }).then(function(resp) {
                        inp.disabled = false;
                        var res = resp.result;
                        if (res && res.success) {
                            var emptyNotice = document.getElementById('projDiscussionEmptyNotice');
                            if (emptyNotice) emptyNotice.remove();

                            var m = res.message;
                            var mDiv = document.createElement('div');
                            mDiv.className = 'd-flex gap-3 justify-content-end';
                            mDiv.innerHTML = '
' +
                                '
You (Customer) • ' + (m.time || 'Just now') + '' +
                                '
' + (m.body || text) + '';
                            box.appendChild(mDiv);
                            inp.value = '';
                            box.scrollTop = box.scrollHeight;
                        } else {
                            alert('Failed to send message: ' + ((res && res.error) || 'Please try again.'));
                        }
                    }).catch(function(err) {
                        inp.disabled = false;
                        console.error('Error sending discussion reply:', err);
                        alert('Network error while sending message.');
                    });
                }

