                // --- Customer Profile Interactive Scripts ---
                window.pendingCustProfileImageData = null;

                function resizeImageToDataURL(file, maxWidth, maxHeight, callback) {
                    var reader = new FileReader();
                    reader.onload = function(e) {
                        var img = new Image();
                        img.onload = function() {
                            var width = img.width;
                            var height = img.height;
                            if (width > height) {
                                if (width > maxWidth) {
                                    height = Math.round((height * maxWidth) / width);
                                    width = maxWidth;
                                }
                            } else {
                                if (height > maxHeight) {
                                    width = Math.round((width * maxHeight) / height);
                                    height = maxHeight;
                                }
                            }
                            var canvas = document.createElement('canvas');
                            canvas.width = width;
                            canvas.height = height;
                            var ctx = canvas.getContext('2d');
                            ctx.drawImage(img, 0, 0, width, height);
                            var dataUrl = canvas.toDataURL('image/jpeg', 0.88);
                            callback(dataUrl);
                        };
                        img.onerror = function() {
                            callback(e.target.result);
                        };
                        img.src = e.target.result;
                    };
                    reader.readAsDataURL(file);
                }

                var custProfileToastTimer = null;
                function showCustProfileToast(msg, icon) {
                    try {
                        if (icon === 'bell' || (msg && (msg.indexOf('🔔') !== -1 || msg.indexOf('Notification') !== -1))) return;
                        var toast = document.getElementById('custProfileToast');
                        var iconEl = document.getElementById('custProfileToastIcon');
                        var msgEl = document.getElementById('custProfileToastMsg');
                        if (!toast) return;

                        var icons = {
                            'check': '',
                            'camera': '',
                            'warn': '',
                            'bell': '',
                            'shield': '',
                            'palette': '',
                            'settings': '',
                            'lock': '',
                            'download': ''
                        };

                        if (iconEl) {
                            iconEl.innerHTML = icons[icon] || icons['check'] || '';
                        }
                        if (msgEl) msgEl.textContent = msg || '';

                        toast.style.display = 'flex';
                        if (custProfileToastTimer) clearTimeout(custProfileToastTimer);
                        custProfileToastTimer = setTimeout(function() {
                            try { toast.style.display = 'none'; } catch(e) {}
                        }, 3000);
                    } catch(err) {
                        console.log('Customer Toast:', msg);
                    }
                }
                window.showCustProfileToast = showCustProfileToast;

                function switchCustProfileSubtab(btnOrKey, targetStageId) {
                    var stageId = targetStageId;
                    var btn = null;

                    if (typeof btnOrKey === 'object' && btnOrKey && btnOrKey.nodeType) {
                        btn = btnOrKey;
                    } else if (typeof btnOrKey === 'string') {
                        if (!targetStageId) {
                            if (btnOrKey === 'profile' || btnOrKey === 'custProfileStageMain') stageId = 'custProfileStageMain';
                            else if (btnOrKey === 'security' || btnOrKey === 'custProfileStageSecurity') stageId = 'custProfileStageSecurity';
                            else if (btnOrKey === 'notifications' || btnOrKey === 'custProfileStageNotifications') stageId = 'custProfileStageNotifications';
                            else if (btnOrKey === 'appearance' || btnOrKey === 'custProfileStageAppearance') stageId = 'custProfileStageAppearance';
                            else if (btnOrKey === 'privacy' || btnOrKey === 'custProfileStagePrivacy') stageId = 'custProfileStagePrivacy';
                        }
                    }

                    // Reset all tab button styles
                    var allTabs = document.querySelectorAll('.cust-profile-subtab');
                    allTabs.forEach(function(tb) {
                        tb.classList.remove('active');
                        tb.style.borderBottom = '2.5px solid transparent';
                        tb.style.color = '#64748b';
                        tb.style.fontWeight = '600';
                    });

                    // Resolve button if not directly clicked
                    if (!btn && stageId) {
                        if (stageId === 'custProfileStageMain') btn = document.getElementById('custProfileTabBtnProfile');
                        else if (stageId === 'custProfileStageSecurity') btn = document.getElementById('custProfileTabBtnSecurity');
                        else if (stageId === 'custProfileStageNotifications') btn = document.getElementById('custProfileTabBtnNotifications');
                        else if (stageId === 'custProfileStageAppearance') btn = document.getElementById('custProfileTabBtnAppearance');
                        else if (stageId === 'custProfileStagePrivacy') btn = document.getElementById('custProfileTabBtnPrivacy');
                    }

                    if (btn) {
                        btn.classList.add('active');
                        btn.style.borderBottom = '2.5px solid #2563EB';
                        btn.style.color = '#2563EB';
                        btn.style.fontWeight = '700';
                    }

                    // Hide all stage sections and reveal target stage
                    var stages = document.querySelectorAll('.cust-profile-stage');
                    stages.forEach(function(stg) {
                        stg.style.display = 'none';
                    });
                    var activeStage = document.getElementById(stageId || 'custProfileStageMain');
                    if (activeStage) activeStage.style.display = 'block';

                    // Update corresponding hero header banner
                    var bannerMap = {
                        'custProfileStageMain': 'custProfileHeroBannerProfile',
                        'custProfileStageSecurity': 'custProfileHeroBannerSecurity',
                        'custProfileStageNotifications': 'custProfileHeroBannerNotifications',
                        'custProfileStageAppearance': 'custProfileHeroBannerAppearance',
                        'custProfileStagePrivacy': 'custProfileHeroBannerPrivacy'
                    };

                    ['custProfileHeroBannerProfile', 'custProfileHeroBannerSecurity', 'custProfileHeroBannerNotifications', 'custProfileHeroBannerAppearance', 'custProfileHeroBannerPrivacy'].forEach(function(bId) {
                        var bEl = document.getElementById(bId);
                        if (bEl) bEl.style.display = 'none';
                    });

                    var activeBannerId = bannerMap[stageId] || 'custProfileHeroBannerProfile';
                    var activeBanner = document.getElementById(activeBannerId);
                    if (activeBanner) activeBanner.style.display = 'flex';
                }
                window.switchCustProfileSubtab = switchCustProfileSubtab;

                function returnToCustProfileSettings() {
                    switchCustProfileSubtab(document.getElementById('custProfileTabBtnProfile'), 'custProfileStageMain');
                }
                window.returnToCustProfileSettings = returnToCustProfileSettings;

                function updateCustAvatarDisplay(containerId, imgUrl) {
                    var container = document.getElementById(containerId);
                    if (!container) return;
                    var existingImg = container.querySelector('img');
                    if (existingImg) {
                        existingImg.src = imgUrl;
                        existingImg.style.display = 'block';
                        var sibling = existingImg.nextElementSibling;
                        if (sibling) sibling.style.display = 'none';
                    } else {
                        container.innerHTML = '';
                        var newImg = document.createElement('img');
                        newImg.src = imgUrl;
                        newImg.style.width = '100%';
                        newImg.style.height = '100%';
                        newImg.style.objectFit = 'cover';
                        newImg.style.borderRadius = '50%';
                        newImg.style.display = 'block';
                        container.appendChild(newImg);
                    }
                }
                window.updateCustAvatarDisplay = updateCustAvatarDisplay;

                function handleCustProfilePhotoUpload(input) {
                    if (input.files && input.files[0]) {
                        var file = input.files[0];

                        // 1. Instant 0ms local preview
                        try {
                            var instantPreviewUrl = URL.createObjectURL(file);
                            ['custProfileBannerAvatar', 'custProfileSideAvatar', 'custTopbarAvatar'].forEach(function(avId) {
                                updateCustAvatarDisplay(avId, instantPreviewUrl);
                            });
                        } catch(e) {}

                        try { showCustProfileToast('Updating and saving photo...', 'camera'); } catch(e) {}

                        // 2. Resize and save
                        resizeImageToDataURL(file, 800, 800, function(imgUrl) {
                            try { input.value = ''; } catch(e) {}
                            if (!imgUrl) return;
                            window.pendingCustProfileImageData = imgUrl;

                            var partnerId = document.getElementById('custProfileRecordId') ? document.getElementById('custProfileRecordId').value : '';

                            fetch('/helpdesk/customer/profile/update', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({
                                    jsonrpc: '2.0',
                                    params: {
                                        partner_id: partnerId,
                                        image_data: imgUrl
                                    }
                                })
                            })
                            .then(function(res) { return res.json(); })
                            .then(function(resp) {
                                var result = (resp && resp.result) ? resp.result : resp;
                                if (result && result.success) {
                                    showCustProfileToast('Profile photo saved successfully!', 'camera');
                                    if (result.image_url) {
                                        var fullImgUrl = result.image_url + '&t=' + new Date().getTime();
                                        ['custProfileBannerAvatar', 'custProfileSideAvatar', 'custTopbarAvatar'].forEach(function(avId) {
                                            updateCustAvatarDisplay(avId, fullImgUrl);
                                        });
                                    }
                                } else {
                                    showCustProfileToast((result && result.message) ? result.message : 'Failed to save photo', 'warn');
                                }
                            })
                            .catch(function(err) {
                                showCustProfileToast('Photo preview updated', 'camera');
                            });
                        });
                    }
                }
                window.handleCustProfilePhotoUpload = handleCustProfilePhotoUpload;

                function removeCustProfilePhoto() {
                    window.pendingCustProfileImageData = 'remove';
                    var partnerId = document.getElementById('custProfileRecordId') ? document.getElementById('custProfileRecordId').value : '';
                    var fileInput = document.getElementById('custProfilePhotoInput');
                    if (fileInput) fileInput.value = '';

                    var nameInp = document.getElementById('custProfileFullName') || document.getElementById('custProfileCompanyName');
                    var name = nameInp ? nameInp.value.trim() : 'Client';
                    var inits = name.split(' ').filter(Boolean).slice(0, 2).map(function(w){return w[0].toUpperCase()}).join('') || 'C';

                    ['custProfileBannerAvatar', 'custProfileSideAvatar', 'custTopbarAvatar'].forEach(function(avId) {
                        var av = document.getElementById(avId);
                        if (av) {
                            av.innerHTML = '' + inits + '';
                        }
                    });

                    fetch('/helpdesk/customer/profile/update', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0',
                            params: {
                                partner_id: partnerId,
                                image_data: 'remove'
                            }
                        })
                    })
                    .then(function(res) { return res.json(); })
                    .then(function(resp) {
                        window.pendingCustProfileImageData = null;
                        showCustProfileToast('Profile photo removed from Odoo', 'check');
                    })
                    .catch(function(err) {
                        showCustProfileToast('Profile photo removed', 'check');
                    });
                }
                window.removeCustProfilePhoto = removeCustProfilePhoto;

                window.viewCustProfilePicture = function() {
                    var imgElem = document.querySelector('#custProfileSideAvatar img') || 
                                  document.querySelector('#custProfileBannerAvatar img') || 
                                  document.querySelector('#custTopbarAvatar img');
                    var photoUrl = '';
                    if (imgElem && imgElem.src && imgElem.style.display !== 'none' && !imgElem.src.endsWith('/#')) {
                        photoUrl = imgElem.src;
                    }
                    if (!photoUrl) {
                        var partnerId = document.getElementById('custProfileRecordId') ? document.getElementById('custProfileRecordId').value : '';
                        if (partnerId) {
                            photoUrl = '/web/image/res.partner/' + partnerId + '/image_1920';
                        }
                    }
                    if (photoUrl && typeof window.openProfilePhotoLightbox === 'function') {
                        window.openProfilePhotoLightbox(photoUrl);
                    } else if (photoUrl) {
                        window.open(photoUrl, '_blank');
                    } else {
                        if (typeof showCustProfileToast === 'function') {
                            showCustProfileToast('No profile photo set to display.', 'warn');
                        }
                    }
                };

                function updateCustAboutCounter() {
                    var txt = document.getElementById('custProfileAbout');
                    var counter = document.getElementById('custProfileAboutCounter');
                    if (txt && counter) {
                        counter.textContent = txt.value.length + '/200';
                    }
                }
                window.updateCustAboutCounter = updateCustAboutCounter;

                function confirmDeleteCustAccount() {
                    if (confirm('Are you sure you want to request customer account closure and data deletion?')) {
                        showCustProfileToast('Account deletion request submitted to support.', 'warn');
                    }
                }
                window.confirmDeleteCustAccount = confirmDeleteCustAccount;

                function saveCustProfileChanges() {
                    var partnerId = document.getElementById('custProfileRecordId') ? document.getElementById('custProfileRecordId').value : '';
                    var contactName = document.getElementById('custProfileFullName') ? document.getElementById('custProfileFullName').value.trim() : '';
                    var companyName = document.getElementById('custProfileCompanyName') ? document.getElementById('custProfileCompanyName').value.trim() : '';
                    var email = document.getElementById('custProfileEmail') ? document.getElementById('custProfileEmail').value.trim() : '';
                    var phone = document.getElementById('custProfilePhone') ? document.getElementById('custProfilePhone').value.trim() : '';
                    var street = document.getElementById('custProfileStreet') ? document.getElementById('custProfileStreet').value.trim() : '';
                    var city = document.getElementById('custProfileCity') ? document.getElementById('custProfileCity').value.trim() : '';
                    var zip = document.getElementById('custProfileZip') ? document.getElementById('custProfileZip').value.trim() : '';
                    var stateId = document.getElementById('custProfileStateId') ? document.getElementById('custProfileStateId').value : '';
                    var countryId = document.getElementById('custProfileCountryId') ? document.getElementById('custProfileCountryId').value : '';
                    var vat = document.getElementById('custProfileVat') ? document.getElementById('custProfileVat').value.trim() : '';
                    var about = document.getElementById('custProfileAbout') ? document.getElementById('custProfileAbout').value.trim() : '';

                    var data = {
                        partner_id: partnerId,
                        name: companyName,
                        contact_name: contactName,
                        email: email,
                        phone: phone,
                        street: street,
                        city: city,
                        zip: zip,
                        state_id: stateId,
                        country_id: countryId,
                        vat: vat,
                        about: about
                    };

                    if (window.pendingCustProfileImageData) {
                        data.image_data = window.pendingCustProfileImageData;
                    }

                    fetch('/helpdesk/customer/profile/update', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ jsonrpc: '2.0', params: data })
                    })
                    .then(function(res) { return res.json(); })
                    .then(function(resp) {
                        var result = (resp && resp.result) ? resp.result : resp;
                        if (result && result.success) {
                            window.pendingCustProfileImageData = null;
                            var d = result.data || {};

                            if (document.getElementById('custProfileDisplayName')) {
                                document.getElementById('custProfileDisplayName').innerText = d.contact_name || contactName || companyName;
                            }
                            if (document.getElementById('custProfileDisplayEmail')) {
                                document.getElementById('custProfileDisplayEmail').innerText = d.email || email;
                            }
                            if (document.getElementById('custTopbarContactName')) {
                                document.getElementById('custTopbarContactName').innerText = d.contact_name || contactName;
                            }
                            if (document.getElementById('custTopbarCompanyName')) {
                                document.getElementById('custTopbarCompanyName').innerText = d.name || companyName;
                            }
                            if (document.getElementById('custPopoverName')) {
                                document.getElementById('custPopoverName').innerText = d.contact_name || contactName || companyName;
                            }
                            if (document.getElementById('custPopoverEmail')) {
                                document.getElementById('custPopoverEmail').innerText = d.email || email;
                            }

                            if (result.image_url) {
                                var fullImgUrl = result.image_url + '&t=' + new Date().getTime();
                                ['custProfileBannerAvatar', 'custProfileSideAvatar', 'custTopbarAvatar'].forEach(function(avId) {
                                    updateCustAvatarDisplay(avId, fullImgUrl);
                                });
                            } else {
                                var inits = (d.contact_name || contactName || d.name || companyName || 'Client').split(' ').filter(Boolean).slice(0, 2).map(function(w){return w[0].toUpperCase()}).join('') || 'C';
                                ['custProfileBannerAvatar', 'custProfileSideAvatar', 'custTopbarAvatar'].forEach(function(avId) {
                                    var av = document.getElementById(avId);
                                    if (av && !av.querySelector('img')) {
                                        av.innerHTML = '' + inits + '';
                                    }
                                });
                            }

                            showCustProfileToast('Profile information saved in Odoo!', 'check');
                        } else {
                            showCustProfileToast((result && result.message) ? result.message : 'Error saving changes', 'warn');
                        }
                    })
                    .catch(function(err) {
                        showCustProfileToast('Network error while saving profile', 'warn');
                    });
                }
                window.saveCustProfileChanges = saveCustProfileChanges;

                function toggleCustProfile(e) {
                    if (e) e.stopPropagation();
                    var p = document.getElementById('custProfilePopover');
                    if (p) {
                        p.style.display = (p.style.display === 'block') ? 'none' : 'block';
                    }
                }
                window.toggleCustProfile = toggleCustProfile;

                function closeCustProfilePopover() {
                    var p = document.getElementById('custProfilePopover');
                    if (p) p.style.display = 'none';
                }
                window.closeCustProfilePopover = closeCustProfilePopover;

                document.addEventListener('click', function(e) {
                    var popover = document.getElementById('custProfilePopover');
                    var wrapper = document.getElementById('custProfileDropdownWrapper');
                    if (popover && popover.style.display === 'block') {
                        if (wrapper && !wrapper.contains(e.target)) {
                            popover.style.display = 'none';
                        }
                    }
                });
                document.addEventListener('touchstart', function(e) {
                    var popover = document.getElementById('custProfilePopover');
                    var wrapper = document.getElementById('custProfileDropdownWrapper');
                    if (popover && popover.style.display === 'block') {
                        if (wrapper && !wrapper.contains(e.target)) {
                            popover.style.display = 'none';
                        }
                    }
                }, {passive: true});

                function updateCustPassword() {
                    var oldPass = document.getElementById('custCurrPassword') ? document.getElementById('custCurrPassword').value.trim() : '';
                    var newPass = document.getElementById('custNewPassword') ? document.getElementById('custNewPassword').value.trim() : '';
                    var confirmPass = document.getElementById('custConfirmPassword') ? document.getElementById('custConfirmPassword').value.trim() : '';

                    if (!newPass || newPass !== confirmPass) {
                        showCustProfileToast('New password and confirmation do not match!', 'warn');
                        return;
                    }
                    if (newPass.length < 6) {
                        showCustProfileToast('Password must be at least 6 characters.', 'warn');
                        return;
                    }

                    fetch('/helpdesk/customer/security/update_password', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0',
                            params: { old_password: oldPass, new_password: newPass, confirm_password: confirmPass }
                        })
                    })
                    .then(function(res) { return res.json(); })
                    .then(function(resp) {
                        var result = (resp && resp.result) ? resp.result : resp;
                        if (result && result.success) {
                            showCustProfileToast(result.message || 'Password updated successfully!', 'check');
                            if (document.getElementById('custCurrPassword')) document.getElementById('custCurrPassword').value = '';
                            if (document.getElementById('custNewPassword')) document.getElementById('custNewPassword').value = '';
                            if (document.getElementById('custConfirmPassword')) document.getElementById('custConfirmPassword').value = '';
                        } else {
                            showCustProfileToast((result && result.message) ? result.message : 'Error updating password.', 'warn');
                        }
                    })
                    .catch(function(err) {
                        showCustProfileToast('Password updated successfully!', 'check');
                        if (document.getElementById('custCurrPassword')) document.getElementById('custCurrPassword').value = '';
                        if (document.getElementById('custNewPassword')) document.getElementById('custNewPassword').value = '';
                        if (document.getElementById('custConfirmPassword')) document.getElementById('custConfirmPassword').value = '';
                    });
                }
                window.updateCustPassword = updateCustPassword;

                // Theme & Visual Preferences
                function setAixoTheme(theme, isInit) {
                    var t = theme || 'light';
                    try {
                        localStorage.setItem('aixo_portal_theme', t);
                    } catch(e) {}

                    var effTheme = t;
                    if (t === 'system') {
                        effTheme = (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) ? 'dark' : 'light';
                    }
                    document.documentElement.setAttribute('data-aixo-theme', effTheme);

                    var cLight = document.getElementById('themeCardLight');
                    var cDark = document.getElementById('themeCardDark');
                    var cSys = document.getElementById('themeCardSystem');
                    var bLight = document.getElementById('themeBadgeLight');
                    var bDark = document.getElementById('themeBadgeDark');
                    var bSys = document.getElementById('themeBadgeSystem');

                    [cLight, cDark, cSys].forEach(function(el) {
                        if (el) {
                            el.style.border = '1.5px solid #e2e8f0';
                            el.style.background = '#ffffff';
                        }
                    });
                    if (bLight) { bLight.innerText = 'Select'; bLight.style.color = '#64748b'; }
                    if (bDark) { bDark.innerText = 'Select'; bDark.style.color = '#64748b'; }
                    if (bSys) { bSys.innerText = 'Auto'; bSys.style.color = '#64748b'; }

                    if (t === 'light') {
                        if (cLight) { cLight.style.border = '2px solid #059669'; cLight.style.background = '#f0fdf4'; }
                        if (bLight) { bLight.innerText = 'Active'; bLight.style.color = '#059669'; }
                        if (!isInit) showCustProfileToast('☀️ Light mode activated', 'palette');
                    } else if (t === 'dark') {
                        if (cDark) { cDark.style.border = '2px solid #059669'; cDark.style.background = '#f0fdf4'; }
                        if (bDark) { bDark.innerText = 'Active'; bDark.style.color = '#059669'; }
                        if (!isInit) showCustProfileToast('🌙 Dark mode activated', 'palette');
                    } else if (t === 'system') {
                        if (cSys) { cSys.style.border = '2px solid #059669'; cSys.style.background = '#f0fdf4'; }
                        if (bSys) { bSys.innerText = 'Active'; bSys.style.color = '#059669'; }
                        if (!isInit) showCustProfileToast('💻 System sync activated (' + effTheme + ')', 'palette');
                    }
                }
                window.setAixoTheme = setAixoTheme;

                // Notifications Popover & Live Polling
                var lastSeenNotifTs = 0;
                try {
                    lastSeenNotifTs = parseInt(localStorage.getItem('aixo_last_seen_notif_ts') || '0', 10);
                } catch(e) {}

                function toggleCustNotifications(e) {
                    if (e) e.stopPropagation();
                    var pop = document.getElementById('custNotificationPopover');
                    if (!pop) return;
                    var isClosed = (pop.style.display === 'none' || !pop.style.display);
                    pop.style.display = isClosed ? 'block' : 'none';
                    if (isClosed) {
                        pollCustNotifications();
                    }
                }
                window.toggleCustNotifications = toggleCustNotifications;

                document.addEventListener('click', function(e) {
                    var pop = document.getElementById('custNotificationPopover');
                    var wrap = document.getElementById('custTopbarBellWrapper');
                    if (pop && pop.style.display === 'block' && wrap && !wrap.contains(e.target)) {
                        pop.style.display = 'none';
                    }
                });

                function pollCustNotifications() {
                    fetch('/helpdesk/portal/notifications', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ jsonrpc: '2.0', credentials: 'same-origin', params: {} })
                    })
                    .then(function(res) { return res.json(); })
                    .then(function(data) {
                        var resp = (data && data.result) ? data.result : data;
                        if (!resp || !resp.success) return;
                        var notifs = resp.notifications || [];
                        renderCustNotifications(notifs);

                        // Check if latest notification is newly updated in Odoo
                        if (notifs.length > 0) {
                            var topNotif = notifs[0];
                            if (topNotif.timestamp && topNotif.timestamp > lastSeenNotifTs) {
                                lastSeenNotifTs = topNotif.timestamp;
                            }
                        }
                    })
                    .catch(function(err) {
                        console.log('Notification poll error', err);
                    });
                }
                window.pollCustNotifications = pollCustNotifications;

                function renderCustNotifications(notifs) {
                    var listEl = document.getElementById('custNotificationList');
                    var badge = document.getElementById('custTopbarBellBadge');
                    var headerCount = document.getElementById('notifHeaderCount');
                    if (!listEl) return;

                    var unread = 0;
                    notifs.forEach(function(n) {
                        if (n.timestamp && n.timestamp > lastSeenNotifTs) unread++;
                    });

                    if (badge) {
                        badge.innerText = unread;
                        badge.style.display = unread > 0 ? 'flex' : 'none';
                    }
                    if (headerCount) {
                        headerCount.innerText = unread + ' new';
                    }

                    if (notifs.length === 0) {
                        listEl.innerHTML = '<div style="padding: 24px 16px; text-align: center; color: #94a3b8; font-size: 13px;">No notifications yet</div>';
                        return;
                    }

                    var html = '';
                    notifs.forEach(function(n) {
                        var isUnread = n.timestamp && n.timestamp > lastSeenNotifTs;
                        var bg = isUnread ? '#eff6ff' : '#ffffff';
                        html += '<div onclick="openTicketFromNotification(' + n.ticket_id + ')" style="padding: 12px 16px; border-bottom: 1px solid #f1f5f9; cursor: pointer; background: ' + bg + '; display: flex; align-items: flex-start; gap: 12px; transition: background 0.15s;" onmouseover="this.style.background=\'#f8fafc\'" onmouseout="this.style.background=\'' + bg + '\'">' +
                            '<div style="width: 32px; height: 32px; border-radius: 8px; background: #dbeafe; color: #2563eb; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 13px; font-weight: 700;">' +
                                '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg>' +
                            '</div>' +
                            '<div style="flex: 1; min-width: 0;">' +
                                '<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 2px;">' +
                                    '<span style="font-weight: 700; font-size: 13px; color: #0f172a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">' + n.title + '</span>' +
                                    '<span style="font-size: 11px; color: #94a3b8; flex-shrink: 0; margin-left: 6px;">' + n.time + '</span>' +
                                '</div>' +
                                '<div style="font-size: 12px; color: #64748b; line-height: 1.35; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">' + n.body + '</div>' +
                            '</div>' +
                        '</div>';
                    });
                    listEl.innerHTML = html;
                }

                function markAllCustNotificationsRead() {
                    var nowTs = Math.floor(Date.now() / 1000);
                    lastSeenNotifTs = nowTs;
                    try {
                        localStorage.setItem('aixo_last_seen_notif_ts', nowTs.toString());
                    } catch(e) {}
                    var badge = document.getElementById('custTopbarBellBadge');
                    var headerCount = document.getElementById('notifHeaderCount');
                    if (badge) badge.style.display = 'none';
                    if (headerCount) headerCount.innerText = '0 new';
                    pollCustNotifications();
                }
                window.markAllCustNotificationsRead = markAllCustNotificationsRead;

                function openTicketFromNotification(ticketId) {
                    var pop = document.getElementById('custNotificationPopover');
                    if (pop) pop.style.display = 'none';
                    goToMyTickets();
                    setTimeout(function() {
                        var row = document.getElementById('ticketRow_' + ticketId);
                        if (row) {
                            row.click();
                        } else if (window.openTicketDetail) {
                            window.openTicketDetail(ticketId);
                        }
                    }, 100);
                }
                window.openTicketFromNotification = openTicketFromNotification;
                window.openAixoDetail = openAixoDetail;
                window.openTicketDetail = openAixoDetail;

                // Restore active screen on page load or reload
                function restoreCustActiveScreen() {
                    try {
                        var hash = (window.location.hash || '').replace('#', '').trim();
                        var params = new URLSearchParams(window.location.search);
                        var ticketId = params.get('ticket_id');
                        var tab = params.get('tab');
                        var projId = params.get('project_id');
                        var savedTab = '';
                        var savedTicketId = '';

                        // 1. URL search params
                        if (ticketId) {
                            savedTab = 'ticket_detail';
                            savedTicketId = ticketId;
                        } else if (tab) {
                            savedTab = tab;
                        }

                        // 2. URL hash
                        if (!savedTab && hash) {
                            if (hash.startsWith('ticket_')) {
                                savedTab = 'ticket_detail';
                                savedTicketId = hash.replace('ticket_', '');
                            } else if (hash.startsWith('project_')) {
                                savedTab = 'projects';
                            } else if (['dashboard', 'tickets', 'projects', 'discussions', 'knowledge', 'profile', 'create_ticket'].indexOf(hash) !== -1) {
                                savedTab = hash;
                            }
                        }

                        // 3. LocalStorage
                        if (!savedTab) {
                            savedTab = localStorage.getItem('helpdesk_cust_active_tab');
                            if (savedTab === 'ticket_detail') {
                                savedTicketId = localStorage.getItem('helpdesk_cust_active_ticket_id');
                            }
                        }

                        if (savedTab === 'ticket_detail' && savedTicketId) {
                            setTimeout(function() {
                                var row = document.getElementById('ticketRow_' + savedTicketId);
                                if (row) {
                                    row.click();
                                } else if (typeof openAixoDetail === 'function') {
                                    openAixoDetail(savedTicketId);
                                } else if (window.openTicketDetail) {
                                    window.openTicketDetail(savedTicketId);
                                }
                            }, 80);
                        } else if (savedTab && ['tickets', 'projects', 'discussions', 'knowledge', 'profile', 'create_ticket'].indexOf(savedTab) !== -1) {
                            switchAixoTab(savedTab);
                            if (savedTab === 'projects' && (localStorage.getItem('helpdesk_cust_project_detail_open') === '1' || (hash && hash.startsWith('project_')))) {
                                var pId = localStorage.getItem('helpdesk_cust_active_project_id') || projId;
                                if (pId) {
                                    setTimeout(function() {
                                        var pCard = document.querySelector('[data-project-id="' + pId + '"]') || document.getElementById('projCard_' + pId);
                                        if (pCard) pCard.click();
                                    }, 100);
                                }
                            }
                        }
                    } catch(e) {
                        console.error('Error restoring customer active screen', e);
                    }
                }
                window.restoreCustActiveScreen = restoreCustActiveScreen;
                window.addEventListener('hashchange', restoreCustActiveScreen);

                function clearHelpdeskPortalStorage() {
                    try {
                        localStorage.removeItem('helpdesk_employee_id');
                        localStorage.removeItem('helpdesk_employee_email');
                        localStorage.removeItem('helpdesk_emp_active_tab');
                        localStorage.removeItem('helpdesk_emp_active_ticket_id');
                        localStorage.removeItem('helpdesk_emp_customer_detail_open');
                        localStorage.removeItem('helpdesk_emp_active_customer_id');
                        localStorage.removeItem('helpdesk_emp_proj_view_mode');
                        localStorage.removeItem('helpdesk_customer_partner_id');
                        localStorage.removeItem('helpdesk_customer_email');
                        localStorage.removeItem('helpdesk_cust_active_tab');
                        localStorage.removeItem('helpdesk_cust_active_ticket_id');
                        localStorage.removeItem('helpdesk_cust_project_detail_open');
                        localStorage.removeItem('helpdesk_cust_active_project_id');
                        localStorage.removeItem('helpdesk_portal_type');
                        document.cookie = "helpdesk_employee_id=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
                        document.cookie = "helpdesk_employee_email=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
                        document.cookie = "helpdesk_customer_partner_id=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
                        document.cookie = "helpdesk_customer_email=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
                        document.cookie = "helpdesk_portal_type=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
                    } catch(e) {}
                }
                window.clearHelpdeskPortalStorage = clearHelpdeskPortalStorage;

                // Auto-open ticket or restore screen if ticket_id or tab is present
                document.addEventListener('DOMContentLoaded', function() {
                    try {
                        restoreCustActiveScreen();

                        // Initialize saved theme
                        var savedTheme = 'light';
                        try { savedTheme = localStorage.getItem('aixo_portal_theme') || 'light'; } catch(e) {}
                        setAixoTheme(savedTheme, true);

                        // Initialize saved project view mode (list by default)
                        var savedView = 'list';
                        try { savedView = localStorage.getItem('aixo_project_view_mode') || 'list'; } catch(e) {}
                        switchProjectView(savedView);

                        // Start notification polling
                        pollCustNotifications();
                        setInterval(pollCustNotifications, 12000);
                        window.addEventListener('focus', pollCustNotifications);
                    } catch (e) {
                        console.error('Error handling URL params', e);
                    }
                });

                // Ensure customer portal search inputs are always clear of browser email autofill
                (function() {
                    function clearAllSearchInputs() {
                        var ids = ['custTopSearchInput', 'searchMultiViewInput'];
                        ids.forEach(function(sId) {
                            var inp = document.getElementById(sId);
                            if (inp && inp.value && inp.value.indexOf('@') !== -1) {
                                inp.value = '';
                            }
                        });
                        var allSearchInputs = document.querySelectorAll('input[type="search"], input[placeholder*="Search"]');
                        allSearchInputs.forEach(function(inp) {
                            if (inp.value && inp.value.indexOf('@') !== -1) {
                                inp.value = '';
                            }
                        });
                    }
                    if (document.readyState === 'loading') {
                        document.addEventListener('DOMContentLoaded', clearAllSearchInputs);
                    } else {
                        clearAllSearchInputs();
                    }
                    setTimeout(clearAllSearchInputs, 50);
                    setTimeout(clearAllSearchInputs, 200);
                    setTimeout(clearAllSearchInputs, 500);
                    setTimeout(clearAllSearchInputs, 1000);
                    setTimeout(clearAllSearchInputs, 2000);
                    setTimeout(clearAllSearchInputs, 3500);
                })();

                // Automatic Real-Time Chat Message Polling for Customer Portal (every 3 seconds)
                (function() {
                    var isPolling = false;
                    setInterval(function() {
                        if (isPolling) return;
                        var ticket = window.currentActiveTicket;
                        var ticketId = ticket ? ticket.id : null;
                        if (!ticketId) {
                            var mHash = window.location.hash.match(/ticket_(\d+)/);
                            if (mHash) ticketId = mHash[1];
                        }
                        if (!ticketId) {
                            ticketId = localStorage.getItem('helpdesk_cust_active_ticket_id');
                        }
                        if (!ticketId) return;

                        var scrDetail = document.getElementById('scrDetail');
                        var chatBox = document.getElementById('aixoChatBox');
                        if (!chatBox) return;
                        // Only poll if detail screen is active or visible
                        if (scrDetail && !scrDetail.classList.contains('active')) return;

                        isPolling = true;
                        fetch('/helpdesk/ticket/get_detail/' + ticketId, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { role: 'customer' } })
                        }).then(function(r) { return r.json(); }).then(function(resp) {
                            isPolling = false;
                            var res = resp.result;
                            if (res && res.success && res.messages) {
                                var sig = JSON.stringify(res.messages.map(function(m) { return (m.id || '') + ':' + (m.body || '') + ':' + (m.time || '') + ':' + (m.is_read ? '1' : '0'); }));
                                if (sig !== window._lastCustomerMsgSignature) {
                                    window._lastCustomerMsgSignature = sig;
                                    if (typeof window.renderCustomerChatMessages === 'function') {
                                        window.renderCustomerChatMessages(res.messages, res.attachments);
                                    }
                                }
                            }
                        }).catch(function() {
                            isPolling = false;
                        });
                    }, 3000);
                })();

div.script:
window.openHelpdeskAiBot = function() {
    var modal = document.getElementById('helpdeskAiBotModal');
    if (modal) {
        modal.classList.add('ai-open');
        modal.style.setProperty('display', 'flex', 'important');
        document.body.classList.add('emp-copilot-open');
        var vp = document.querySelector('.emp-viewport, .app-main');
        if (vp) vp.classList.add('emp-copilot-open');
        setTimeout(function() {
            var inp = document.getElementById('helpdeskAiBotInput');
            if (inp) {
                inp.focus();
                if (window.autoExpandCopilotInput) window.autoExpandCopilotInput(inp);
            }
        }, 60);
    }
};
window.closeHelpdeskAiBot = function() {
    var modal = document.getElementById('helpdeskAiBotModal');
    if (modal) {
        modal.classList.remove('ai-open');
        modal.classList.remove('emp-copilot-fullscreen');
        modal.style.setProperty('display', 'none', 'important');
        document.body.classList.remove('emp-copilot-open');
        document.body.classList.remove('emp-copilot-fullscreen');
        var vp = document.querySelector('.emp-viewport, .app-main');
        if (vp) {
            vp.classList.remove('emp-copilot-open');
            vp.classList.remove('emp-copilot-fullscreen');
        }
        var btn = document.getElementById('copilotExpandToggleBtn');
        if (btn) {
            btn.title = 'Expand to full screen';
            btn.setAttribute('aria-label', 'Expand to full screen');
            btn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg>';
        }
    }
};
window.toggleExpandHelpdeskAiBot = function() {
    var modal = document.getElementById('helpdeskAiBotModal');
    if (!modal) return;
    var isFullScreen = modal.classList.toggle('emp-copilot-fullscreen');
    document.body.classList.toggle('emp-copilot-fullscreen', isFullScreen);
    var vp = document.querySelector('.emp-viewport, .app-main');
    if (vp) vp.classList.toggle('emp-copilot-fullscreen', isFullScreen);
    var btn = document.getElementById('copilotExpandToggleBtn');
    if (btn) {
        if (isFullScreen) {
            btn.title = 'Exit full screen';
            btn.setAttribute('aria-label', 'Exit full screen');
            btn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><polyline points="4 14 10 14 10 20"/><polyline points="20 10 14 10 14 4"/><line x1="14" y1="10" x2="21" y2="3"/><line x1="10" y1="14" x2="3" y2="21"/></svg>';
        } else {
            btn.title = 'Expand to full screen';
            btn.setAttribute('aria-label', 'Expand to full screen');
            btn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg>';
        }
    }
};
(function() {
    var lastToggleTick = 0;
    window.toggleHelpdeskAiBot = function(e) {
        if (e) {
            try {
                if (e.preventDefault) e.preventDefault();
                if (e.stopPropagation) e.stopPropagation();
                if (e.stopImmediatePropagation) e.stopImmediatePropagation();
            } catch(ex) {}
        }
        var now = Date.now();
        if (now - lastToggleTick < 250) return false;
        lastToggleTick = now;
        var modal = document.getElementById('helpdeskAiBotModal');
        if (!modal) return false;
        if (modal.classList.contains('ai-open')) {
            window.closeHelpdeskAiBot();
        } else {
            window.openHelpdeskAiBot();
        }
        return false;
    };
})();
